/* SSC CHSL — English Chapter-Wise PYQs (6 chapters × 50 MCQs = 300 PYQ-style questions · 30 min · +2 / -0.50) */
(function (root) {
  'use strict';

  function hash(v) {
    let r = 2166136261;
    for (let i = 0; i < v.length; i++) { r ^= v.charCodeAt(i); r = Math.imul(r, 16777619); }
    return r >>> 0;
  }
  function shuffle(a, seed) {
    const r = a.slice(); let s = seed >>> 0;
    for (let i = r.length - 1; i > 0; i--) { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; const j = s % (i + 1); [r[i], r[j]] = [r[j], r[i]]; }
    return r;
  }
  function buildQuestion(id, item, seed) {
    const choices = [item.c, ...item.d];
    const opts = shuffle(choices, seed);
    return {
      id,
      topic: item.t,
      question: item.q,
      options: opts,
      answer: opts.indexOf(item.c),
      explanation: item.e,
      shortcut: item.s
    };
  }

  const RAW_CHAPTERS = [{"id": "ch-eng-errors", "title": "Error Detection & Grammar", "subtitle": "Subject-Verb Agreement, Tenses, Conditionals, Prepositions & Modifiers", "questions": [{"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"Neither of the boys (A) / were present (B) / in the class today (C) / No error (D)\"", "c": "(B) were present", "d": ["(A) Neither of the boys", "(C) in the class today", "(D) No error"], "e": "'Neither of' followed by a plural noun takes a singular verb. Therefore, 'were present' should be replaced with 'was present'.", "s": "Each, Every, Either, Neither + of + plural noun -> always singular verb."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"Each of the students (A) / have submitted (B) / the assignment on time (C) / No error (D)\"", "c": "(B) have submitted", "d": ["(A) Each of the students", "(C) the assignment on time", "(D) No error"], "e": "The distributive pronoun 'Each of' takes a singular verb even when followed by a plural noun. Replace 'have submitted' with 'has submitted'.", "s": "'Each of' always treats members individually, so pair it with a singular verb."}, {"t": "Subject-Verb Agreement", "q": "Spot the segment with a grammatical error: \"The captain along with / his team members / were awarded a trophy / on the stage.\"", "c": "were awarded a trophy", "d": ["The captain along with", "his team members", "on the stage"], "e": "When two subjects are joined by 'along with', the verb agrees with the first subject ('The captain', singular). Thus, 'were awarded a trophy' should be 'was awarded a trophy'.", "s": "With 'along with', 'together with', or 'with', match the verb to Subject 1."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"My brother as well as (A) / his close friends (B) / are planning a trip (C) / No error (D)\"", "c": "(C) are planning a trip", "d": ["(A) My brother as well as", "(B) his close friends", "(D) No error"], "e": "With 'as well as', the verb agrees with the first subject ('My brother', singular). Replace 'are planning a trip' with 'is planning a trip'.", "s": "Subject 1 + as well as + Subject 2 -> verb follows Subject 1."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"One of the finest actors (A) / in the film industry (B) / are retiring next month (C) / No error (D)\"", "c": "(C) are retiring next month", "d": ["(A) One of the finest actors", "(B) in the film industry", "(D) No error"], "e": "'One of the + plural noun' takes a singular verb because the true subject is 'One'. Replace 'are retiring next month' with 'is retiring next month'.", "s": "One of + plural noun + singular verb."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"The number of accidents (A) / on this highway (B) / have increased recently (C) / No error (D)\"", "c": "(C) have increased recently", "d": ["(A) The number of accidents", "(B) on this highway", "(D) No error"], "e": "'The number of + plural noun' denotes a single figure and takes a singular verb. Replace 'have increased recently' with 'has increased recently'.", "s": "'The number of' -> singular verb; 'A number of' -> plural verb."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"Many a brave mountaineer (A) / have tried to climb (B) / this steep Himalayan peak (C) / No error (D)\"", "c": "(B) have tried to climb", "d": ["(A) Many a brave mountaineer", "(C) this steep Himalayan peak", "(D) No error"], "e": "The structure 'Many a + singular noun' always takes a singular verb. Replace 'have tried to climb' with 'has tried to climb'.", "s": "Many a + singular noun + singular verb; Many + plural noun + plural verb."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"Slow and steady (A) / win the race (B) / in the long run (C) / No error (D)\"", "c": "(B) win the race", "d": ["(A) Slow and steady", "(C) in the long run", "(D) No error"], "e": "'Slow and steady' expresses a single unified idea and takes a singular verb. Replace 'win the race' with 'wins the race'.", "s": "Paired phrases representing one idea (bread and butter, slow and steady) take a singular verb."}, {"t": "Subject-Verb Agreement", "q": "Spot the segment with a grammatical error: \"More than one student / were absent from / the morning assembly / last Monday.\"", "c": "were absent from", "d": ["More than one student", "the morning assembly", "last Monday"], "e": "'More than one' followed by a singular noun takes a singular verb. Replace 'were absent from' with 'was absent from'.", "s": "'More than one' + singular noun -> singular verb."}, {"t": "Subject-Verb Agreement", "q": "Identify the segment that contains a grammatical error: \"Not only the principal (A) / but also the teachers (B) / was present at the meeting (C) / No error (D)\"", "c": "(C) was present at the meeting", "d": ["(A) Not only the principal", "(B) but also the teachers", "(D) No error"], "e": "With 'Not only ... but also', the verb agrees with the nearer subject ('the teachers', plural). Replace 'was present at the meeting' with 'were present at the meeting'.", "s": "For 'Either...or', 'Neither...nor', 'Not only...but also', verb matches the nearest subject."}, {"t": "Inversion", "q": "Identify the segment that contains a grammatical error: \"Hardly I had stepped (A) / out of the house (B) / when it began to rain (C) / No error (D)\"", "c": "(A) Hardly I had stepped", "d": ["(B) out of the house", "(C) when it began to rain", "(D) No error"], "e": "When a sentence starts with a negative adverb like 'Hardly', subject-verb inversion is required. Replace 'Hardly I had stepped' with 'Hardly had I stepped'.", "s": "Negative adverb at start -> Auxiliary verb comes before the subject (Hardly + had + subject)."}, {"t": "Inversion & Correlatives", "q": "Identify the segment that contains a grammatical error: \"No sooner did the bell ring (A) / when the students (B) / rushed out of the classroom (C) / No error (D)\"", "c": "(B) when the students", "d": ["(A) No sooner did the bell ring", "(C) rushed out of the classroom", "(D) No error"], "e": "'No sooner' is always paired with the conjunction 'than', not 'when'. Replace 'when the students' with 'than the students'.", "s": "No sooner ... than; Hardly / Scarcely ... when."}, {"t": "Inversion & Correlatives", "q": "Identify the segment that contains a grammatical error: \"Scarcely had he reached (A) / the railway station (B) / than the train departed (C) / No error (D)\"", "c": "(C) than the train departed", "d": ["(A) Scarcely had he reached", "(B) the railway station", "(D) No error"], "e": "'Scarcely' takes the correlative conjunction 'when' (or 'before'), never 'than'. Replace 'than the train departed' with 'when the train departed'.", "s": "Scarcely / Hardly always pair with 'when', never 'than'."}, {"t": "Inversion", "q": "Spot the segment with a grammatical error: \"Seldom we have seen / such a magnificent performance / by a young artist / on this stage.\"", "c": "Seldom we have seen", "d": ["such a magnificent performance", "by a young artist", "on this stage"], "e": "Starting a sentence with 'Seldom' requires inversion of the auxiliary verb and subject. Replace 'Seldom we have seen' with 'Seldom have we seen'.", "s": "Seldom / Never / Rarely at the start -> Auxiliary + Subject + Main verb."}, {"t": "Inversion", "q": "Identify the segment that contains a grammatical error: \"Not only he broke (A) / the traffic rules (B) / but also argued with the officer (C) / No error (D)\"", "c": "(A) Not only he broke", "d": ["(B) the traffic rules", "(C) but also argued with the officer", "(D) No error"], "e": "When 'Not only' opens a sentence, it triggers inversion. Replace 'Not only he broke' with 'Not only did he break'.", "s": "'Not only' at the beginning requires 'did/had/aux + subject'."}, {"t": "Conditionals", "q": "Identify the segment that contains a grammatical error: \"If he would have worked hard, (A) / he would have passed (B) / the examination easily (C) / No error (D)\"", "c": "(A) If he would have worked hard,", "d": ["(B) he would have passed", "(C) the examination easily", "(D) No error"], "e": "In a Type 3 conditional, the 'if'-clause uses the past perfect ('had + V3'), not 'would have'. Replace 'If he would have worked hard,' with 'If he had worked hard,'.", "s": "Type 3 Conditional: If + Subject + had + V3, Subject + would have + V3."}, {"t": "Conditionals", "q": "Identify the segment that contains a grammatical error: \"If I was the Prime Minister, (A) / I would eradicate poverty (B) / from the country (C) / No error (D)\"", "c": "(A) If I was the Prime Minister,", "d": ["(B) I would eradicate poverty", "(C) from the country", "(D) No error"], "e": "Hypothetical or unreal present conditions take the subjunctive 'were' for all subjects. Replace 'If I was the Prime Minister,' with 'If I were the Prime Minister,'.", "s": "Unreal/imaginary present wish or condition -> always use 'were', never 'was'."}, {"t": "Conditionals", "q": "Spot the segment with a grammatical error: \"If it will rain tomorrow, / we shall cancel / the outdoor event / without delay.\"", "c": "If it will rain tomorrow,", "d": ["we shall cancel", "the outdoor event", "without delay"], "e": "In a Type 1 conditional, the 'if'-clause takes the simple present tense, not 'will'. Replace 'If it will rain tomorrow,' with 'If it rains tomorrow,'.", "s": "Never use 'will' or 'shall' inside an 'if' / 'when' / 'unless' condition clause."}, {"t": "Conditionals", "q": "Identify the segment that contains a grammatical error: \"Had I known about his arrival, (A) / I would meet him (B) / at the airport (C) / No error (D)\"", "c": "(B) I would meet him", "d": ["(A) Had I known about his arrival,", "(C) at the airport", "(D) No error"], "e": "'Had I known' is an inverted Type 3 conditional ('If I had known'), so the main clause must take 'would have + V3'. Replace 'I would meet him' with 'I would have met him'.", "s": "Had + S + V3 ... S + would have + V3."}, {"t": "Conditionals", "q": "Identify the segment that contains a grammatical error: \"Unless you do not work hard, (A) / you cannot succeed (B) / in this competitive exam (C) / No error (D)\"", "c": "(A) Unless you do not work hard,", "d": ["(B) you cannot succeed", "(C) in this competitive exam", "(D) No error"], "e": "'Unless' already means 'if not', so using 'do not' creates a double negative. Replace 'Unless you do not work hard,' with 'Unless you work hard,'.", "s": "Unless = If + not; never put 'not' inside the 'unless' clause."}, {"t": "Tenses", "q": "Identify the segment that contains a grammatical error: \"It is raining heavily (A) / since early morning (B) / in the coastal region (C) / No error (D)\"", "c": "(A) It is raining heavily", "d": ["(B) since early morning", "(C) in the coastal region", "(D) No error"], "e": "An action that started in the past ('since early morning') and continues into the present requires the present perfect continuous tense. Replace 'It is raining heavily' with 'It has been raining heavily'.", "s": "'Since/For + time' with ongoing action -> has/have been + V-ing."}, {"t": "Tenses", "q": "Identify the segment that contains a grammatical error: \"I have completed (A) / my graduation in 2021 (B) / from a reputed university (C) / No error (D)\"", "c": "(A) I have completed", "d": ["(B) my graduation in 2021", "(C) from a reputed university", "(D) No error"], "e": "Specific finished past time markers like 'in 2021' require the simple past tense, not the present perfect. Replace 'I have completed' with 'I completed'.", "s": "Finished past time (yesterday, ago, in 2021) -> always Simple Past (V2)."}, {"t": "Tenses", "q": "Spot the segment with a grammatical error: \"The patient died / before the doctor / arrived at the clinic / late at night.\"", "c": "The patient died", "d": ["before the doctor", "arrived at the clinic", "late at night"], "e": "When two past actions happen sequentially, the earlier action takes the past perfect ('had + V3'). Replace 'The patient died' with 'The patient had died'.", "s": "Earlier past action = had + V3; later past action = V2."}, {"t": "Tenses", "q": "Identify the segment that contains a grammatical error: \"It is high time (A) / we start preparing (B) / for the final examination (C) / No error (D)\"", "c": "(B) we start preparing", "d": ["(A) It is high time", "(C) for the final examination", "(D) No error"], "e": "Expressions like 'It is time' and 'It is high time' followed by a subject take the simple past (V2) form. Replace 'we start preparing' with 'we started preparing'.", "s": "It is high time + Subject + V2 (past subjunctive)."}, {"t": "Tenses", "q": "Identify the segment that contains a grammatical error: \"The teacher told us (A) / that the earth revolved (B) / around the sun (C) / No error (D)\"", "c": "(B) that the earth revolved", "d": ["(A) The teacher told us", "(C) around the sun", "(D) No error"], "e": "Universal truths and scientific facts remain in the simple present tense even when the reporting verb is in the past tense. Replace 'that the earth revolved' with 'that the earth revolves'.", "s": "Universal truths never shift to past tense in indirect speech."}, {"t": "Tenses", "q": "Identify the segment that contains a grammatical error: \"By the time we reach the theatre, (A) / the movie will already start (B) / without us (C) / No error (D)\"", "c": "(B) the movie will already start", "d": ["(A) By the time we reach the theatre,", "(C) without us", "(D) No error"], "e": "'By the time + simple present' pairs with the future perfect tense ('will have + V3') to show an action completed before a future point. Replace 'the movie will already start' with 'the movie will have already started'.", "s": "By the time + Simple Present -> Future Perfect (will have + V3)."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"I prefer coffee (A) / than tea in (B) / the morning hours (C) / No error (D)\"", "c": "(B) than tea in", "d": ["(A) I prefer coffee", "(C) the morning hours", "(D) No error"], "e": "The verb 'prefer' takes the fixed preposition 'to' when comparing two nouns, never 'than'. Replace 'than tea in' with 'to tea in'.", "s": "Prefer + Noun 1 + to + Noun 2 (never 'than')."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"He is senior than me (A) / by three years (B) / in this department (C) / No error (D)\"", "c": "(A) He is senior than me", "d": ["(B) by three years", "(C) in this department", "(D) No error"], "e": "Latin comparatives ending in '-ior' (senior, junior, superior, inferior, prior) take 'to' instead of 'than'. Replace 'He is senior than me' with 'He is senior to me'.", "s": "Words ending in '-ior' (senior, junior, superior, prior) take 'to'."}, {"t": "Fixed Prepositions", "q": "Spot the segment with a grammatical error: \"We discussed about / the new project plan / during the meeting / in the conference hall.\"", "c": "We discussed about", "d": ["the new project plan", "during the meeting", "in the conference hall"], "e": "'Discuss' is a transitive verb meaning 'to talk about', so 'about' after it is redundant. Replace 'We discussed about' with 'We discussed'.", "s": "Verbs like discuss, describe, order, emphasize take NO preposition in active voice."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"The committee comprises of (A) / five senior members (B) / from different ministries (C) / No error (D)\"", "c": "(A) The committee comprises of", "d": ["(B) five senior members", "(C) from different ministries", "(D) No error"], "e": "In the active voice, 'comprise' means 'consist of' and does not take 'of'. Replace 'The committee comprises of' with 'The committee comprises'.", "s": "Comprise = consist of (no 'of' after 'comprise' in active voice)."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"The thief entered into (A) / the house quietly (B) / through the back door (C) / No error (D)\"", "c": "(A) The thief entered into", "d": ["(B) the house quietly", "(C) through the back door", "(D) No error"], "e": "'Enter' does not take 'into' when referring to physically going inside a place. Replace 'The thief entered into' with 'The thief entered'.", "s": "Enter + place (no 'into'); 'enter into' is only for agreements/discussions."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"The doctor advised him (A) / to abstain of (B) / alcohol and smoking (C) / No error (D)\"", "c": "(B) to abstain of", "d": ["(A) The doctor advised him", "(C) alcohol and smoking", "(D) No error"], "e": "The verb 'abstain' is always followed by the fixed preposition 'from'. Replace 'to abstain of' with 'to abstain from'.", "s": "Abstain / refrain / prevent / prohibit -> always followed by 'from'."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"The young man was (A) / accused for stealing (B) / the diamond necklace (C) / No error (D)\"", "c": "(B) accused for stealing", "d": ["(A) The young man was", "(C) the diamond necklace", "(D) No error"], "e": "The verb 'accuse' takes the fixed preposition 'of', not 'for'. Replace 'accused for stealing' with 'accused of stealing'.", "s": "Accused of, acquitted of, guilty of, convicted of."}, {"t": "Fixed Prepositions", "q": "Spot the segment with a grammatical error: \"She found it difficult / to cope up with / the heavy workload / at her new office.\"", "c": "to cope up with", "d": ["She found it difficult", "the heavy workload", "at her new office"], "e": "The correct phrasal verb is 'cope with' (meaning manage); 'cope up with' is a common redundancy error. Replace 'to cope up with' with 'to cope with'.", "s": "Always 'cope with', never 'cope up with'."}, {"t": "Fixed Prepositions", "q": "Identify the segment that contains a grammatical error: \"Despite of his illness, (A) / he attended the (B) / annual board meeting (C) / No error (D)\"", "c": "(A) Despite of his illness,", "d": ["(B) he attended the", "(C) annual board meeting", "(D) No error"], "e": "'Despite' means 'in spite of' and never takes the preposition 'of'. Replace 'Despite of his illness,' with 'Despite his illness,'.", "s": "Despite = In spite of (never write 'despite of')."}, {"t": "Articles", "q": "Identify the segment that contains a grammatical error: \"He is a honest man (A) / who always speaks (B) / the truth in court (C) / No error (D)\"", "c": "(A) He is a honest man", "d": ["(B) who always speaks", "(C) the truth in court", "(D) No error"], "e": "The 'h' in 'honest' is silent, so the word begins with a vowel sound and requires 'an'. Replace 'He is a honest man' with 'He is an honest man'.", "s": "Choose a/an by sound, not spelling: silent 'h' (honest, hour, heir) -> 'an'."}, {"t": "Articles", "q": "Identify the segment that contains a grammatical error: \"She wants to study (A) / in an European university (B) / after her graduation (C) / No error (D)\"", "c": "(B) in an European university", "d": ["(A) She wants to study", "(C) after her graduation", "(D) No error"], "e": "'European' begins with a consonant 'y' sound (/j/), so it takes 'a' rather than 'an'. Replace 'in an European university' with 'in a European university'.", "s": "Words starting with 'yu' sound (European, university, union) take 'a'."}, {"t": "Articles", "q": "Identify the segment that contains a grammatical error: \"Mount Everest is (A) / a highest peak (B) / in the entire world (C) / No error (D)\"", "c": "(B) a highest peak", "d": ["(A) Mount Everest is", "(C) in the entire world", "(D) No error"], "e": "A superlative degree adjective ('highest') takes the definite article 'the'. Replace 'a highest peak' with 'the highest peak'.", "s": "Superlative adjectives (best, highest, tallest) always take 'the'."}, {"t": "Articles", "q": "Identify the segment that contains a grammatical error: \"The more you read, (A) / more you learn (B) / about the world (C) / No error (D)\"", "c": "(B) more you learn", "d": ["(A) The more you read,", "(C) about the world", "(D) No error"], "e": "Parallel increase structures require 'the' before both comparative adjectives/adverbs ('The + comparative ..., the + comparative ...'). Replace 'more you learn' with 'the more you learn'.", "s": "Parallel comparatives: The + comparative ..., the + comparative ..."}, {"t": "Articles", "q": "Spot the segment with a grammatical error: \"My younger sister knows how / to play violin / very melodiously / during school functions.\"", "c": "to play violin", "d": ["My younger sister knows how", "very melodiously", "during school functions"], "e": "The definite article 'the' is used before the names of musical instruments after 'play'. Replace 'to play violin' with 'to play the violin'.", "s": "Always use 'the' before musical instruments (play the piano, play the violin)."}, {"t": "Pronouns", "q": "Identify the segment that contains a grammatical error: \"Between you and I, (A) / the new manager is (B) / quite strict about deadlines (C) / No error (D)\"", "c": "(A) Between you and I,", "d": ["(B) the new manager is", "(C) quite strict about deadlines", "(D) No error"], "e": "Prepositions like 'between' must be followed by objective-case pronouns ('me', not 'I'). Replace 'Between you and I,' with 'Between you and me,'.", "s": "Preposition + Objective pronoun (between you and me, let you and him)."}, {"t": "Pronouns", "q": "Identify the segment that contains a grammatical error: \"One should always keep (A) / his promises in order (B) / to earn respect (C) / No error (D)\"", "c": "(B) his promises in order", "d": ["(A) One should always keep", "(C) to earn respect", "(D) No error"], "e": "When 'one' is used as an indefinite subject pronoun, its possessive form is 'one's', not 'his'. Replace 'his promises in order' with 'one's promises in order'.", "s": "Pronoun consistency: 'One' as subject always pairs with 'one's'."}, {"t": "Pronouns", "q": "Identify the segment that contains a grammatical error: \"You must avail (A) / of every opportunity (B) / that comes your way (C) / No error (D)\"", "c": "(A) You must avail", "d": ["(B) of every opportunity", "(C) that comes your way", "(D) No error"], "e": "The verb 'avail' takes a reflexive pronoun before 'of'. Replace 'You must avail' with 'You must avail yourself'.", "s": "Verbs like avail, enjoy, absent, acquit require a reflexive pronoun when no object follows."}, {"t": "Pronouns", "q": "Identify the segment that contains a grammatical error: \"I, you and he (A) / will go together (B) / to the exhibition tomorrow (C) / No error (D)\"", "c": "(A) I, you and he", "d": ["(B) will go together", "(C) to the exhibition tomorrow", "(D) No error"], "e": "For positive or neutral actions, singular pronouns follow the 2-3-1 order (2nd person, 3rd person, 1st person). Replace 'I, you and he' with 'You, he and I'.", "s": "Good/neutral action: 231 order (You, he and I); mistake/confession: 123 order."}, {"t": "Pronouns", "q": "Spot the segment with a grammatical error: \"The two brothers / always help one another / in times of crisis / without any hesitation.\"", "c": "always help one another", "d": ["The two brothers", "in times of crisis", "without any hesitation"], "e": "'Each other' is used for two persons or things, whereas 'one another' is used for more than two. Replace 'always help one another' with 'always help each other'.", "s": "Two -> each other; More than two -> one another."}, {"t": "Question Tags", "q": "Identify the segment that contains a grammatical error: \"I am responsible (A) / for this project, (B) / amn't I? (C) / No error (D)\"", "c": "(C) amn't I?", "d": ["(A) I am responsible", "(B) for this project,", "(D) No error"], "e": "The negative question tag for 'I am' is 'aren't I?', as 'amn't I' is ungrammatical in standard English. Replace 'amn't I?' with 'aren't I?'.", "s": "Question tag for 'I am' is always 'aren't I?'; for 'I am not' is 'am I?'."}, {"t": "Question Tags", "q": "Identify the segment that contains a grammatical error: \"He seldom visits (A) / his hometown nowadays, (B) / doesn't he? (C) / No error (D)\"", "c": "(C) doesn't he?", "d": ["(A) He seldom visits", "(B) his hometown nowadays,", "(D) No error"], "e": "Words like 'seldom', 'hardly', and 'scarcely' are negative in meaning, so they take a positive question tag. Replace 'doesn't he?' with 'does he?'.", "s": "Negative sense words (seldom, rarely, barely, little, few) take a POSITIVE tag."}, {"t": "Question Tags", "q": "Identify the segment that contains a grammatical error: \"Let us organize a farewell party (A) / for our senior colleague, (B) / will we? (C) / No error (D)\"", "c": "(C) will we?", "d": ["(A) Let us organize a farewell party", "(B) for our senior colleague,", "(D) No error"], "e": "Imperative sentences beginning with 'Let us' or 'Let's' always take the question tag 'shall we?'. Replace 'will we?' with 'shall we?'.", "s": "Let's / Let us -> always 'shall we?'."}, {"t": "Modifiers", "q": "Identify the segment that contains a grammatical error: \"Walking along the road, (A) / a stray dog bit (B) / the little boy (C) / No error (D)\"", "c": "(A) Walking along the road,", "d": ["(B) a stray dog bit", "(C) the little boy", "(D) No error"], "e": "'Walking along the road' is a dangling modifier that illogically modifies 'a stray dog' instead of 'the little boy'. It should be 'While the boy was walking along the road,'.", "s": "Opening participle phrase must share its subject with the main clause's subject."}, {"t": "Modifiers", "q": "Identify the segment that contains a grammatical error: \"He is enough intelligent (A) / to solve this puzzle (B) / within five minutes (C) / No error (D)\"", "c": "(A) He is enough intelligent", "d": ["(B) to solve this puzzle", "(C) within five minutes", "(D) No error"], "e": "When 'enough' modifies an adjective or adverb, it must be placed after the adjective, not before it. Replace 'He is enough intelligent' with 'He is intelligent enough'.", "s": "Positive-degree Adjective + enough (intelligent enough); enough + Noun (enough money)."}]}, {"id": "ch-eng-vocab", "title": "Synonyms & Antonyms", "subtitle": "High-Frequency SSC CGL / CHSL Tier-I Vocabulary PYQs", "questions": [{"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: UBIQUITOUS", "c": "Omnipresent", "d": ["Scarce", "Clandestine", "Ephemeral"], "e": "'Ubiquitous' means seeming to be everywhere at the same time, making 'Omnipresent' its exact synonym.", "s": "Root 'ubique' (Latin) = everywhere; 'omni' = all, 'present' = everywhere."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: EPHEMERAL", "c": "Transitory", "d": ["Perpetual", "Eternal", "Enduring"], "e": "'Ephemeral' means lasting for a very short time, which is synonymous with 'Transitory'.", "s": "Ephemeral = lasting for a day / short-lived (like a butterfly's life)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: MAGNANIMOUS", "c": "Generous", "d": ["Vindictive", "Petty", "Stingy"], "e": "'Magnanimous' describes someone generous or forgiving, especially toward a rival or less powerful person.", "s": "Magn (great) + animus (spirit/soul) = great-hearted, generous."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: OSTENTATIOUS", "c": "Showy", "d": ["Modest", "Unassuming", "Plain"], "e": "'Ostentatious' means characterized by vulgar or pretentious display designed to impress, matching 'Showy'.", "s": "Ostentatious = showing off wealth or status loudly."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: PRAGMATIC", "c": "Practical", "d": ["Idealistic", "Quixotic", "Visionary"], "e": "'Pragmatic' means dealing with things sensibly and realistically in a way based on practical considerations.", "s": "Pragmatic starts with 'Pra' -> Practical!"}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: MITIGATE", "c": "Alleviate", "d": ["Aggravate", "Intensify", "Exacerbate"], "e": "'Mitigate' means to make something less severe, harmful, or painful, which is synonymous with 'Alleviate'.", "s": "Mitigate = make mild/less severe (antonyms: aggravate, exacerbate)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: ALTRUISTIC", "c": "Benevolent", "d": ["Mercenary", "Selfish", "Egoistic"], "e": "'Altruistic' means showing a selfless concern for the well-being of others, matching 'Benevolent'.", "s": "Root 'alter' (other) -> caring for others selflessly."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: CACOPHONY", "c": "Discord", "d": ["Euphony", "Harmony", "Melody"], "e": "'Cacophony' refers to a harsh, discordant mixture of sounds, matching 'Discord'.", "s": "Caco (bad/harsh) + phon (sound) = harsh noise; Euphony = pleasant sound."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: AMBIGUOUS", "c": "Vague", "d": ["Explicit", "Lucid", "Unmistakable"], "e": "'Ambiguous' means open to more than one interpretation and lacking clarity, synonymous with 'Vague'.", "s": "Ambi (both/two) -> two meanings -> unclear/vague."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: BENEVOLENT", "c": "Kindhearted", "d": ["Malevolent", "Ruthless", "Hostile"], "e": "'Benevolent' means well-meaning and kindly, making 'Kindhearted' its direct synonym.", "s": "Root 'bene' (good) -> wishing good for others."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: CLANDESTINE", "c": "Secret", "d": ["Overt", "Candid", "Public"], "e": "'Clandestine' means kept secret or done secretively, especially because it is illicit.", "s": "Clandestine = hidden/secret (like a covert meeting)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: DILIGENT", "c": "Industrious", "d": ["Indolent", "Sluggish", "Negligent"], "e": "'Diligent' means having or showing care and conscientious effort in one's work, synonymous with 'Industrious'.", "s": "Diligent = hardworking and careful = industrious."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: FASTIDIOUS", "c": "Meticulous", "d": ["Careless", "Sloppy", "Indifferent"], "e": "'Fastidious' means very attentive to and concerned about accuracy and detail, matching 'Meticulous'.", "s": "Fastidious = fussy about every tiny detail = meticulous."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: GARRULOUS", "c": "Talkative", "d": ["Taciturn", "Reticent", "Laconic"], "e": "'Garrulous' means excessively talkative, especially on trivial matters.", "s": "Garrulous = talks non-stop (antonyms: taciturn, reticent, laconic)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: GREGARIOUS", "c": "Sociable", "d": ["Reclusive", "Solitary", "Introverted"], "e": "'Gregarious' describes someone fond of company and enjoying social interaction, matching 'Sociable'.", "s": "Root 'greg' (flock/herd) -> loves being in a group = sociable."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: IMPECCABLE", "c": "Flawless", "d": ["Defective", "Blemished", "Tainted"], "e": "'Impeccable' means in accordance with the highest standards and free from any fault, synonymous with 'Flawless'.", "s": "Im (not) + peccare (to sin/fault) = without fault = flawless."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: LETHARGIC", "c": "Sluggish", "d": ["Energetic", "Vivacious", "Brisk"], "e": "'Lethargic' means affected by extreme lack of energy and sluggishness.", "s": "Lethargic = lazy, slow, lacking energy = sluggish."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: MENDACIOUS", "c": "Untruthful", "d": ["Veracious", "Candid", "Honest"], "e": "'Mendacious' means not telling the truth and lying habitually, synonymous with 'Untruthful'.", "s": "Mendacious = lying/false; Veracious = truthful (ver = truth)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: OBSOLETE", "c": "Outdated", "d": ["Contemporary", "Modern", "Current"], "e": "'Obsolete' means no longer produced or used because something newer exists, matching 'Outdated'.", "s": "Obsolete = old and out of use = outdated."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: PERNICIOUS", "c": "Harmful", "d": ["Beneficial", "Salubrious", "Innocuous"], "e": "'Pernicious' means having a harmful effect, especially in a gradual or subtle way.", "s": "Pernicious = deadly/harmful (antonym: innocuous, salubrious)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: PRODIGAL", "c": "Extravagant", "d": ["Frugal", "Thrifty", "Parsimonious"], "e": "'Prodigal' means spending money or resources freely and recklessly, matching 'Extravagant'.", "s": "Prodigal = wasteful spender (all three distractors mean thrifty/stingy!)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: RESILIENT", "c": "Flexible", "d": ["Brittle", "Fragile", "Rigid"], "e": "'Resilient' means able to withstand or recover quickly from difficult conditions or bend without breaking, matching 'Flexible'.", "s": "Resilient = bounces back easily (opposite of brittle/rigid)."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: SAGACIOUS", "c": "Wise", "d": ["Foolish", "Naive", "Obtuse"], "e": "'Sagacious' means having or showing keen mental discernment and good judgment, synonymous with 'Wise'.", "s": "Think of a 'sage' -> a sage is always wise!"}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: TENACIOUS", "c": "Persistent", "d": ["Yielding", "Irresolute", "Fickle"], "e": "'Tenacious' means tending to keep a firm hold of something and refusing to give up, matching 'Persistent'.", "s": "Root 'ten' (hold) -> holds on firmly = persistent."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: VENERATE", "c": "Revere", "d": ["Despise", "Scorn", "Disdain"], "e": "'Venerate' means to regard with great respect and reverence, matching 'Revere'.", "s": "Venerate = deep respect (same root as 'venerable')."}, {"t": "Synonyms", "q": "Select the most appropriate SYNONYM of the given word: ZEALOUS", "c": "Enthusiastic", "d": ["Apathetic", "Indifferent", "Lukewarm"], "e": "'Zealous' means having or showing great energy or enthusiasm in pursuit of a cause or objective.", "s": "Zeal = passion/enthusiasm -> Zealous = enthusiastic."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: ABSTRUSE", "c": "Lucid", "d": ["Obscure", "Cryptic", "Esoteric"], "e": "'Abstruse' means difficult to understand or obscure; its exact antonym is 'Lucid' (clear and easy to understand).", "s": "Abstruse = hard to grasp; Lucid = crystal clear."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: ACQUITTAL", "c": "Conviction", "d": ["Exoneration", "Pardon", "Release"], "e": "'Acquittal' is a judgment that a person is not guilty of a crime, so its opposite is 'Conviction'.", "s": "Acquit (declare innocent) <-> Convict (declare guilty)."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: ADVERSITY", "c": "Prosperity", "d": ["Misfortune", "Calamity", "Hardship"], "e": "'Adversity' refers to a difficult or unlucky situation; its antonym is 'Prosperity'.", "s": "Adversity (hard times) <-> Prosperity (good fortune/wealth)."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: AMELIORATE", "c": "Worsen", "d": ["Improve", "Enhance", "Reform"], "e": "'Ameliorate' means to make something bad or unsatisfactory better; its opposite is 'Worsen'.", "s": "Root 'melior' (better) -> Ameliorate = improve <-> Worsen."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: ARDUOUS", "c": "Effortless", "d": ["Strenuous", "Grueling", "Laborious"], "e": "'Arduous' means involving or requiring strenuous effort and difficulty; its antonym is 'Effortless'.", "s": "Arduous = very hard/tiring <-> Effortless."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: AUDACIOUS", "c": "Timid", "d": ["Bold", "Daring", "Intrepid"], "e": "'Audacious' means showing a willingness to take surprisingly bold risks; its opposite is 'Timid'.", "s": "Audacious = daring/bold <-> Timid = shy/fearful."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: BELLIGERENT", "c": "Peaceful", "d": ["Hostile", "Pugnacious", "Aggressive"], "e": "'Belligerent' means hostile and eager to fight; its antonym is 'Peaceful'.", "s": "Root 'belli' (war) -> Belligerent = warlike <-> Peaceful."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: CAPRICIOUS", "c": "Steadfast", "d": ["Fickle", "Whimsical", "Erratic"], "e": "'Capricious' means given to sudden and unaccountable changes of mood or behavior; its opposite is 'Steadfast'.", "s": "Capricious = unpredictable/fickle <-> Steadfast = firm and steady."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: COHERENT", "c": "Disjointed", "d": ["Logical", "Consistent", "Articulate"], "e": "'Coherent' means logical, consistent, and clearly connected; its antonym is 'Disjointed'.", "s": "Coherent = sticks together logically <-> Disjointed = disconnected."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: CONCISE", "c": "Verbose", "d": ["Brief", "Succinct", "Terse"], "e": "'Concise' means giving a lot of information clearly and in a few words; its opposite is 'Verbose' (using too many words).", "s": "Concise = brief & crisp <-> Verbose = overly wordy."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: COPIOUS", "c": "Scarce", "d": ["Abundant", "Plentiful", "Profuse"], "e": "'Copious' means abundant in supply or quantity; its antonym is 'Scarce'.", "s": "Copious = plenty/abundant <-> Scarce = rare/lacking."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: CREDULOUS", "c": "Skeptical", "d": ["Gullible", "Naive", "Trusting"], "e": "'Credulous' means having or showing too great a readiness to believe things; its opposite is 'Skeptical'.", "s": "Root 'cred' (believe) -> Credulous = easily fooled <-> Skeptical = doubtful."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: DEFERENCE", "c": "Contempt", "d": ["Respect", "Reverence", "Esteem"], "e": "'Deference' means humble submission and respect; its antonym is 'Contempt'.", "s": "Deference = polite respect <-> Contempt = scorn/disrespect."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: DISPARAGE", "c": "Praise", "d": ["Belittle", "Denigrate", "Criticize"], "e": "'Disparage' means to regard or represent as being of little worth; its antonym is 'Praise'.", "s": "Disparage = put down/belittle <-> Praise = admire/compliment."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: DORMANT", "c": "Active", "d": ["Latent", "Inactive", "Slumbering"], "e": "'Dormant' means having normal physical functions suspended or slowed down (as if asleep); its antonym is 'Active'.", "s": "Root 'dorm' (sleep, like dormitory) -> Dormant = sleeping <-> Active."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: ECSTASY", "c": "Agony", "d": ["Bliss", "Rapture", "Euphoria"], "e": "'Ecstasy' means an overwhelming feeling of great happiness or joyful excitement; its opposite is 'Agony'.", "s": "Ecstasy = extreme joy <-> Agony = extreme pain/suffering."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: FRUGAL", "c": "Extravagant", "d": ["Thrifty", "Economical", "Stingy"], "e": "'Frugal' means sparing or economical with regard to money or food; its antonym is 'Extravagant'.", "s": "Frugal = careful spender <-> Extravagant = lavish spender."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: HYPOCRISY", "c": "Sincerity", "d": ["Deceit", "Pretense", "Duplicity"], "e": "'Hypocrisy' is the practice of claiming to have moral standards or beliefs to which one's own behavior does not conform; its opposite is 'Sincerity'.", "s": "Hypocrisy = fake virtue/pretense <-> Sincerity = honesty/genuineness."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: IMPERVIOUS", "c": "Vulnerable", "d": ["Resistant", "Impenetrable", "Immune"], "e": "'Impervious' means unable to be affected or penetrated by something; its antonym is 'Vulnerable'.", "s": "Impervious = unaffected/shielded <-> Vulnerable = easily harmed."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: INDIGENOUS", "c": "Foreign", "d": ["Native", "Aboriginal", "Domestic"], "e": "'Indigenous' means originating or occurring naturally in a particular place (native); its antonym is 'Foreign'.", "s": "Indigenous = native/local <-> Foreign = from outside."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: INNOCUOUS", "c": "Harmful", "d": ["Harmless", "Benign", "Safe"], "e": "'Innocuous' means not harmful or offensive; its exact antonym is 'Harmful'.", "s": "In (not) + noc (harm) = harmless <-> Harmful."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: LOQUACIOUS", "c": "Taciturn", "d": ["Talkative", "Garrulous", "Voluble"], "e": "'Loquacious' means tending to talk a great deal; its antonym is 'Taciturn' (reserved or uncommunicative in speech).", "s": "Root 'loqu' (speak) -> Loquacious = talkative <-> Taciturn = silent."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: MOROSE", "c": "Cheerful", "d": ["Gloomy", "Sullen", "Melancholic"], "e": "'Morose' means sullen and ill-tempered or gloomy; its antonym is 'Cheerful'.", "s": "Morose = sad/gloomy <-> Cheerful = happy/bright."}, {"t": "Antonyms", "q": "Select the most appropriate ANTONYM of the given word: NOVICE", "c": "Veteran", "d": ["Beginner", "Tyro", "Apprentice"], "e": "'Novice' means a person new to or inexperienced in a field or situation; its antonym is 'Veteran'.", "s": "Root 'nov' (new) -> Novice = beginner <-> Veteran = experienced expert."}]}, {"id": "ch-eng-idioms", "title": "Idioms & Phrases", "subtitle": "Repeated SSC Idioms, Phrases & Phrasal Verbs", "questions": [{"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Bite the bullet\"", "c": "Face a difficult situation with courage and determination", "d": ["Avoid a painful confrontation by running away", "Speak harshly to someone without thinking", "Waste precious time on trivial matters"], "e": "'Bite the bullet' means to endure a painful or otherwise unpleasant situation that is unavoidable with courage.", "s": "Originates from soldiers biting a bullet during surgery to endure pain bravely."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"At the drop of a hat\"", "c": "Without any hesitation; immediately", "d": ["After careful and lengthy deliberation", "In a careless and clumsy manner", "Only when forced by circumstances"], "e": "'At the drop of a hat' means doing something immediately, willingly, and without any prior hesitation.", "s": "Like starting a race the instant a hat drops -> immediately!"}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Burn the midnight oil\"", "c": "Work or study late into the night", "d": ["Spend money recklessly on luxuries", "Destroy evidence to hide a mistake", "Wake up early before sunrise every day"], "e": "'Burn the midnight oil' means to stay up late working or studying, especially by artificial light.", "s": "Using an oil lamp at midnight = studying/working late at night."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Break a leg\"", "c": "Wish someone good luck before a performance", "d": ["Cause deliberate injury to a competitor", "Cancel an event at the last minute", "Suffer a severe financial loss"], "e": "'Break a leg' is a theatrical expression used to wish a performer good luck before going on stage.", "s": "Theater superstition: saying the opposite ('Break a leg') wishes good luck!"}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Crocodile tears\"", "c": "Insincere or fake display of sorrow", "d": ["Uncontrollable weeping due to deep grief", "Tears shed out of extreme joy", "Crying loudly to frighten others"], "e": "'Crocodile tears' refers to an insincere, hypocritical show of sadness or sympathy.", "s": "Myth that crocodiles weep while eating prey -> fake/pretended sorrow."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Hobson's choice\"", "c": "A seemingly free choice where there is really no alternative", "d": ["A wide variety of attractive options to pick from", "A difficult decision made after consulting experts", "An unfair advantage given to a favored candidate"], "e": "'Hobson's choice' describes a 'take it or leave it' situation in which only one option is actually offered.", "s": "Thomas Hobson offered riders only the horse nearest the door -> take it or leave it (no real choice)."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Achilles' heel\"", "c": "A fatal weakness or vulnerable point", "d": ["A source of extraordinary physical strength", "A lifelong loyal friend or ally", "A sudden victory against strong odds"], "e": "'Achilles' heel' denotes a small but fatal weakness in an otherwise strong person or system.", "s": "Greek warrior Achilles was invulnerable everywhere except his heel -> fatal weak spot."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Spill the beans\"", "c": "Reveal a secret accidentally or prematurely", "d": ["Spoil a meal through careless cooking", "Hide important information from everyone", "Make a complete mess of a simple task"], "e": "'Spill the beans' means to disclose secret or confidential information, often unintentionally.", "s": "Knocking over the jar of voting beans -> letting the secret out!"}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"A bolt from the blue\"", "c": "A sudden and unexpected shock or event", "d": ["A welcome gift received on a special occasion", "A gradual and predictable change in weather", "A brilliant idea that solves a problem"], "e": "'A bolt from the blue' means an event or piece of news that is completely sudden and unexpected, like lightning from a clear sky.", "s": "Lightning bolt from a clear blue sky = total unexpected shock."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"A blessing in disguise\"", "c": "Something that seems bad at first but results in good", "d": ["A deceptive trap hidden behind false promises", "An obvious stroke of good luck from the start", "A minor error that causes a major disaster"], "e": "'A blessing in disguise' describes an apparent misfortune that eventually turns out to be beneficial.", "s": "Good thing wearing a 'bad' disguise -> bad at first, good in the end."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"A white elephant\"", "c": "A costly possession that is useless or burdensome to maintain", "d": ["A rare and priceless treasure of great utility", "A short-lived success that brings quick profit", "An honest person among corrupt colleagues"], "e": "'A white elephant' refers to a possession that is expensive to maintain and brings little or no practical benefit.", "s": "Sacred white elephants cost a fortune to feed and couldn't be used for work -> costly burden."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Add fuel to the fire\"", "c": "Make an already bad situation worse", "d": ["Resolve a heated argument peacefully", "Provide timely help to someone in need", "Start a profitable new business venture"], "e": "'Add fuel to the fire' means to say or do something that intensifies an existing conflict or bad situation.", "s": "Pouring fuel on fire makes it blaze harder -> worsening a bad situation."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"An axe to grind\"", "c": "Have a selfish or ulterior motive", "d": ["Be ready to forgive an old enemy", "Work tirelessly without expecting any reward", "Lack the necessary skills for a job"], "e": "To 'have an axe to grind' means to have a private, selfish reason for doing or saying something.", "s": "Asking someone to turn the grindstone just to sharpen your own axe = selfish motive."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Apple of one's eye\"", "c": "Someone cherished above all others", "d": ["A person who causes constant trouble", "An envious rival in the workplace", "A stranger met briefly during travel"], "e": "'Apple of one's eye' refers to a person whom someone loves and cherishes dearly.", "s": "The pupil ('apple') of the eye is precious and carefully protected -> beloved person."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"At sixes and sevens\"", "c": "In a state of total confusion and disorder", "d": ["Arranged neatly in alphabetical order", "Living happily in complete harmony", "Being strictly punctual at all times"], "e": "'At sixes and sevens' means in a state of confusion, disarray, or disagreement.", "s": "Scattered dice numbers (6 and 7) -> total disorder and confusion."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Back to the drawing board\"", "c": "Start over again from the beginning after a failure", "d": ["Celebrate the successful completion of a project", "Delegate routine work to junior staff", "Continue with a flawed plan stubbornly"], "e": "'Back to the drawing board' means returning to the planning stage because an earlier attempt failed.", "s": "Design failed -> go back to the drawing board to plan afresh."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Barking up the wrong tree\"", "c": "Accuse or pursue the wrong person or course of action", "d": ["Search carefully until the truth is found", "Speak bravely against social injustice", "Warn someone about an approaching danger"], "e": "'Barking up the wrong tree' means following a mistaken line of inquiry or accusing the wrong person.", "s": "Hunting dog barking at a tree the prey isn't in -> chasing/blaming the wrong target."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Beat around the bush\"", "c": "Avoid coming to the main point", "d": ["Speak directly and bluntly without tact", "Search thoroughly through dense bushes", "Reveal confidential details openly"], "e": "'Beat around the bush' means to discuss a matter indirectly and avoid addressing the main issue.", "s": "Beating around the bush instead of flushing out the bird -> avoiding the main topic."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Blow one's own trumpet\"", "c": "Praise oneself boastfully", "d": ["Play a musical instrument in an orchestra", "Warn people about an upcoming storm", "Applaud a colleague's achievement generously"], "e": "'Blow one's own trumpet' means to brag or boast about one's own achievements or abilities.", "s": "Blowing your own trumpet to draw attention to yourself = boasting."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Break the ice\"", "c": "Initiate conversation to relieve awkwardness or tension", "d": ["End a friendly relationship permanently", "Argue fiercely over minor differences", "Take a dangerous risk in freezing weather"], "e": "'Break the ice' means to do or say something to overcome initial stiffness or awkwardness in a social setting.", "s": "Breaking frozen ice so ships can move -> easing initial social stiffness."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Burn one's bridges\"", "c": "Destroy all chances of going back to a previous situation", "d": ["Build stronger relationships with new neighbors", "Cross a river safely during heavy floods", "Forget past mistakes and move forward peacefully"], "e": "'Burn one's bridges' means to act in a way that eliminates any possibility of returning or reconciling later.", "s": "Burning the bridge behind you means there is no turning back!"}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Bury the hatchet\"", "c": "End a conflict and make peace", "d": ["Hide a weapon to attack someone later", "Dig up old grievances to restart a quarrel", "Work hard on a farm throughout the day"], "e": "'Bury the hatchet' means to end a quarrel or conflict and become friendly again.", "s": "Burying weapons in the ground symbolized making peace between tribes."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"By leaps and bounds\"", "c": "Very rapidly or swiftly", "d": ["Slowly and with great hesitation", "In an irregular and unpredictable way", "After overcoming minor obstacles"], "e": "'By leaps and bounds' means progressing or growing very quickly and dramatically.", "s": "Moving in giant leaps and bounds = extremely fast progress."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Call it a day\"", "c": "Stop working for the rest of the day", "d": ["Postpone a meeting until next month", "Begin a difficult task early in the morning", "Cancel an agreement permanently"], "e": "'Call it a day' means to decide to stop doing a task or working because enough has been done for the day.", "s": "Declaring the day's work finished -> wrapping up for the day."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Caught red-handed\"", "c": "Caught in the very act of committing a wrongdoing", "d": ["Arrested based solely on false rumors", "Injured while handling dangerous chemicals", "Praised publicly for an act of bravery"], "e": "'Caught red-handed' means caught right in the middle of committing a crime or wrongful act.", "s": "Originally meant caught with blood on one's hands -> caught in the act."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Cost an arm and a leg\"", "c": "Be extremely expensive", "d": ["Require physical strength rather than money", "Be available free of charge", "Cause a minor inconvenience"], "e": "'Cost an arm and a leg' means to be extraordinarily expensive or require a huge amount of money.", "s": "Paying with your arm and leg = ridiculously high price."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Cry over spilt milk\"", "c": "Regret something already done that cannot be undone", "d": ["Complain loudly about minor daily inconveniences", "Refuse to accept help from close friends", "Celebrate a small gain prematurely"], "e": "'Cry over spilt milk' means to waste time feeling sorry about a past mistake or loss that cannot be fixed.", "s": "Spilt milk cannot be put back in the glass -> useless regret over the past."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Cut corners\"", "c": "Do something carelessly or cheaply to save time or money", "d": ["Take the shortest scenic route while travelling", "Follow every safety rule with utmost precision", "Refuse to compromise on quality at any cost"], "e": "'Cut corners' means to do a task poorly or skip important steps in order to save time, effort, or money.", "s": "Skipping corners while driving or building -> taking cheap/careless shortcuts."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Devil's advocate\"", "c": "One who argues against an idea merely to test its validity", "d": ["A corrupt lawyer who defends notorious criminals", "Someone who blindly agrees with every opinion", "A person who spreads malicious gossip secretly"], "e": "A 'devil's advocate' is someone who expresses an opposing or contentious view to provoke debate or test the strength of an argument.", "s": "Advocating the opposite side just to stress-test an idea."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Every cloud has a silver lining\"", "c": "Every difficult situation has a hopeful or positive aspect", "d": ["Dark clouds always bring destructive thunderstorms", "Good fortune never lasts for a very long time", "Wealthy people can easily buy their way out of trouble"], "e": "'Every cloud has a silver lining' means that even the bleakest situation contains some element of hope or benefit.", "s": "Dark storm cloud edged with bright silver sunlight = hope inside hardship."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Face the music\"", "c": "Accept the unpleasant consequences of one's actions", "d": ["Enjoy a lively concert with close friends", "Blame others for one's own mistakes", "Escape punishment by telling clever lies"], "e": "'Face the music' means to confront and accept criticism, punishment, or the unpleasant results of one's actions.", "s": "Facing the band/audience when things go wrong -> accepting consequences bravely."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Feather in one's cap\"", "c": "An achievement to be proud of", "d": ["A decorative item worn only at festivals", "An unnecessary burden added to one's duties", "A foolish mistake remembered for years"], "e": "A 'feather in one's cap' refers to a notable success or accomplishment of which one can feel proud.", "s": "Hunters/warriors earned a feather in their cap for each feat -> proud achievement."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Gift of the gab\"", "c": "The ability to speak fluently and persuasively", "d": ["A habit of spreading baseless rumors", "An expensive present given on a birthday", "The talent of writing humorous poetry"], "e": "'Gift of the gab' means natural eloquence and the ability to speak easily and persuasively.", "s": "'Gab' = talk/chatter -> natural talent for persuasive speaking."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Hit the nail on the head\"", "c": "Say or do something exactly right", "d": ["Hurt oneself accidentally while working", "Miss a crucial opportunity by a narrow margin", "Repeat an obvious fact unnecessarily"], "e": "'Hit the nail on the head' means to describe a situation or pinpoint the exact answer accurately.", "s": "Striking the nail squarely on its head = getting something 100% right."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"In hot water\"", "c": "In serious trouble or difficulty", "d": ["Enjoying a relaxing spa vacation", "Safe from all external dangers", "Working in a comfortable environment"], "e": "To be 'in hot water' means to be in trouble, distress, or disfavor because of something one has done.", "s": "Boiling hot water = uncomfortable, serious trouble."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Keep at arm's length\"", "c": "Maintain a safe distance and avoid intimacy", "d": ["Welcome a guest with great warmth and affection", "Measure an object accurately without tools", "Help a friend closely during tough times"], "e": "'Keep at arm's length' means to avoid becoming too friendly or closely involved with someone or something.", "s": "Holding someone an arm's distance away -> keeping them emotionally/socially distant."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Leave no stone unturned\"", "c": "Make every possible effort to achieve something", "d": ["Give up easily after facing initial resistance", "Search carelessly without a clear plan", "Build a strong wall using heavy stones"], "e": "'Leave no stone unturned' means to try every conceivable method or search exhaustively to accomplish a goal.", "s": "Turning over every single stone to find treasure -> trying every possible effort."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Make both ends meet\"", "c": "Earn just enough money to cover basic living expenses", "d": ["Accumulate vast wealth within a short period", "Borrow heavily to fund an extravagant lifestyle", "Connect two distant roads with a bridge"], "e": "'Make both ends meet' means to manage to pay for one's basic needs with the limited money one earns.", "s": "Income and expenses meeting cleanly at the end of the month -> surviving on modest income."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Miss the boat\"", "c": "Miss an opportunity by being too slow", "d": ["Travel safely across a wide river", "Arrive early to secure the best seat", "Reject an unfair offer decisively"], "e": "'Miss the boat' means to lose a favorable chance or opportunity by failing to act quickly enough.", "s": "Arriving at the dock after the boat sailed -> missing a golden opportunity."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Nip in the bud\"", "c": "Stop something undesirable at an early stage before it grows", "d": ["Allow a problem to grow until it becomes unmanageable", "Protect delicate garden plants from winter frost", "Delay a decision until the final deadline"], "e": "'Nip in the bud' means to halt a problem or bad habit early before it can develop further.", "s": "Pinching off a flower bud before it blooms -> stopping trouble at the very start."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Once in a blue moon\"", "c": "Very rarely; almost never", "d": ["Every night without exception", "At regular monthly intervals", "During sudden weather changes"], "e": "'Once in a blue moon' describes something that happens extremely rarely.", "s": "A second full moon in a month ('blue moon') is rare -> happens very rarely."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Piece of cake\"", "c": "Something very easy to achieve or do", "d": ["A sweet reward given after hard labor", "A task requiring extraordinary skill and patience", "A fragile object that breaks easily"], "e": "'Piece of cake' means an activity or task that is remarkably simple and effortless to accomplish.", "s": "Eating a slice of cake is effortless -> super easy task."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Pull someone's leg\"", "c": "Tease or joke with someone playfully", "d": ["Physically trip someone during a race", "Offer genuine support during an injury", "Criticize someone harshly in public"], "e": "'Pull someone's leg' means to deceive someone playfully as a joke or tease them good-naturedly.", "s": "Playfully tugging a leg -> teasing/joking with someone."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Read between the lines\"", "c": "Understand the hidden or implied meaning", "d": ["Read a passage quickly without understanding details", "Correct spelling errors in a manuscript", "Memorize a textbook word for word"], "e": "'Read between the lines' means to look for or discover a meaning that is implied rather than explicitly stated.", "s": "Reading the invisible message in the blank spaces between lines -> catching hidden meaning."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Sit on the fence\"", "c": "Remain neutral and avoid taking sides", "d": ["Take a bold stand on a controversial issue", "Guard a property vigilantly day and night", "Rest briefly after finishing hard labor"], "e": "'Sit on the fence' means to avoid making a decision or choosing a side in a dispute.", "s": "Sitting on the fence between two yards = refusing to pick either side."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Take with a pinch of salt\"", "c": "View something with skepticism and not believe it completely", "d": ["Accept every statement as absolute truth", "Add extra flavor to bland food", "Reject an honest apology angrily"], "e": "'Take with a pinch of salt' means to regard a claim or story as exaggerated and accept it only with doubt.", "s": "A pinch of salt makes questionable claims easier to swallow -> treat with skepticism."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Through thick and thin\"", "c": "Under all circumstances, both good and bad", "d": ["Only during times of prosperity and joy", "Without paying attention to minor details", "After passing through a narrow passage"], "e": "'Through thick and thin' means remaining loyal and supportive through every difficulty as well as good times.", "s": "Thick (good/plentiful) and thin (hard/lean) times = in all circumstances."}, {"t": "Idioms", "q": "Select the most appropriate meaning of the given idiom: \"Turn a deaf ear\"", "c": "Refuse to listen or pay attention", "d": ["Listen sympathetically to someone's grievances", "Suffer from a temporary hearing problem", "Respond promptly to an urgent request"], "e": "'Turn a deaf ear' means to deliberately ignore someone's plea, advice, or warning.", "s": "Turning your 'deaf' ear toward someone = pretending not to hear / ignoring."}, {"t": "Phrasal Verbs", "q": "Select the most appropriate meaning of the given phrasal verb: \"Call off\"", "c": "Cancel a planned event or activity", "d": ["Postpone an appointment to next week", "Announce the winners of a contest", "Start a program ahead of schedule"], "e": "The phrasal verb 'call off' means to cancel something that was planned, such as a meeting, strike, or match.", "s": "Call OFF = switch off/cancel; Put OFF = postpone/delay."}, {"t": "Phrasal Verbs", "q": "Select the most appropriate meaning of the given phrasal verb: \"Put off\"", "c": "Postpone or delay something to a later time", "d": ["Extinguish a fire immediately", "Cancel an event permanently", "Wear new clothes for a special occasion"], "e": "The phrasal verb 'put off' means to postpone or delay an event or task to a later date.", "s": "Put OFF = postpone; Put OUT = extinguish; Put ON = wear."}]}, {"id": "ch-eng-ows", "title": "One-Word Substitution", "subtitle": "Phobias, Manias, Killings, Governance, Professions & General OWS", "questions": [{"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: Government by the wealthy.", "c": "Plutocracy", "d": ["Oligarchy", "Theocracy", "Aristocracy"], "e": "Plutocracy refers to a system of government in which power is held by the wealthy class (from Greek 'ploutos' meaning wealth).", "s": "Root 'pluto' = wealth + 'cracy' = rule."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: Government by a small group of all-powerful persons.", "c": "Oligarchy", "d": ["Autocracy", "Plutocracy", "Democracy"], "e": "Oligarchy is a form of government in which a small group of people exercises control over a country or organization.", "s": "Root 'olig' = few + 'archy' = rule."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: Government by the nobles or upper class.", "c": "Aristocracy", "d": ["Bureaucracy", "Mobocracy", "Autocracy"], "e": "Aristocracy is a form of government in which power is held by the nobility or highest social class.", "s": "Root 'aristos' = best/noble + 'cracy' = rule."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: Government by one person with absolute power.", "c": "Autocracy", "d": ["Oligarchy", "Anarchy", "Plutocracy"], "e": "Autocracy is a system of government in which one person possesses absolute, unlimited power.", "s": "Root 'auto' = self/one + 'cracy' = rule."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: Government run by officials of the state.", "c": "Bureaucracy", "d": ["Theocracy", "Aristocracy", "Gerontocracy"], "e": "Bureaucracy is a system of government in which most important decisions are taken by state officials rather than elected representatives.", "s": "'Bureau' (office/desk) + 'cracy' (rule) = rule by officeholders."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: Government by religious leaders or in the name of God.", "c": "Theocracy", "d": ["Monarchy", "Plutocracy", "Autocracy"], "e": "Theocracy is a system of government in which priests or religious leaders rule in the name of God or a god.", "s": "Root 'theo' = God/religion + 'cracy' = rule."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: A state of lawlessness and disorder due to the absence of government.", "c": "Anarchy", "d": ["Monarchy", "Autonomy", "Oligarchy"], "e": "Anarchy refers to a state of disorder due to the absence or nonrecognition of authority and government.", "s": "Prefix 'an-' (without) + 'archy' (rule) = without rule."}, {"t": "Governance", "q": "Select the option that can be used as a one-word substitute for the given group of words: A government run by corrupt and thieving leaders.", "c": "Kleptocracy", "d": ["Kakistocracy", "Neocracy", "Meritocracy"], "e": "Kleptocracy describes a government whose corrupt leaders use political power to steal their country's wealth and resources.", "s": "Root 'klepto' = steal (like kleptomania) + 'cracy' = rule."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The scientific study of birds.", "c": "Ornithology", "d": ["Entomology", "Herpetology", "Ichthyology"], "e": "Ornithology is the branch of zoology dedicated to the scientific study of birds.", "s": "Root 'ornith' = bird + 'logy' = study."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The scientific study of insects.", "c": "Entomology", "d": ["Ornithology", "Etymology", "Mycology"], "e": "Entomology is the scientific study of insects, whereas etymology is the study of word origins.", "s": "Do not confuse 'entomology' (insects) with 'etymology' (words)."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The study of human origins, societies, and cultural development.", "c": "Anthropology", "d": ["Archaeology", "Sociology", "Ethnology"], "e": "Anthropology is the comprehensive study of human beings, their origin, behaviour, and physical, social, and cultural development.", "s": "Root 'anthropo' = mankind/human + 'logy' = study."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The study of ancient human history through the excavation of artifacts and remains.", "c": "Archaeology", "d": ["Anthropology", "Palaeontology", "Geology"], "e": "Archaeology is the study of human history and prehistory through the excavation of sites and analysis of artifacts.", "s": "Root 'archaeo' = ancient + 'logy' = study."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The study of the origin and historical development of words.", "c": "Etymology", "d": ["Entomology", "Philology", "Semantics"], "e": "Etymology is the study of the origin of words and the way in which their meanings have changed throughout history.", "s": "Root 'etymo' = true sense of a word + 'logy' = study."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who compiles a dictionary.", "c": "Lexicographer", "d": ["Cartographer", "Calligrapher", "Choreographer"], "e": "A lexicographer is a person who writes, edits, or compiles dictionaries.", "s": "'Lexicon' = dictionary + 'grapher' = writer/compiler."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who draws or makes maps.", "c": "Cartographer", "d": ["Lexicographer", "Topographer", "Cryptographer"], "e": "A cartographer is a specialist who draws, designs, and produces maps or charts.", "s": "'Carto' (chart/map) + 'grapher' (drawer/writer)."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person skilled in the art of beautiful handwriting.", "c": "Calligrapher", "d": ["Stenographer", "Graphologist", "Typographer"], "e": "A calligrapher is someone skilled in the art of producing decorative, beautiful handwriting or lettering.", "s": "Root 'kalli' = beautiful + 'grapher' = writer."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The scientific study of earthquakes.", "c": "Seismology", "d": ["Meteorology", "Volcanology", "Cosmology"], "e": "Seismology is the branch of geophysics concerned with earthquakes and the propagation of elastic waves through the Earth.", "s": "Root 'seismos' = shaking/earthquake + 'logy' = study."}, {"t": "Study & Professions", "q": "Select the option that can be used as a one-word substitute for the given group of words: The study or collection of coins and currency.", "c": "Numismatics", "d": ["Philately", "Heraldry", "Epigraphy"], "e": "Numismatics is the study or collection of currency, including coins, tokens, paper money, and medals.", "s": "'Numisma' = coin; contrast with 'philately' (stamps)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who unselfishly cares for the welfare of others.", "c": "Altruist", "d": ["Egoist", "Hedonist", "Ascetic"], "e": "An altruist is a person who shows disinterested and selfless concern for the well-being of others.", "s": "Root 'alter' = other; altruistic = for others."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who hates mankind and avoids human society.", "c": "Misanthrope", "d": ["Philanthropist", "Misogamist", "Recluse"], "e": "A misanthrope is a person who dislikes humankind in general and avoids human society.", "s": "'Mis-' (hate) + 'anthrope' (mankind)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who hates or is prejudiced against women.", "c": "Misogynist", "d": ["Misanthrope", "Misogamist", "Patriarch"], "e": "A misogynist is a person who dislikes, despises, or is strongly prejudiced against women.", "s": "'Mis-' (hate) + 'gyne' (woman)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A lover of mankind who helps others through charitable donations.", "c": "Philanthropist", "d": ["Misanthrope", "Mercenary", "Beneficiary"], "e": "A philanthropist is a person who seeks to promote the welfare of others, especially by donating money to good causes.", "s": "'Phil-' (love) + 'anthrop' (mankind)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who knows and can speak many languages.", "c": "Polyglot", "d": ["Monolingual", "Orator", "Linguist"], "e": "A polyglot is a person who knows and is able to speak or use several languages.", "s": "'Poly' (many) + 'glot' (tongue/language)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A shy person who turns thoughts inward and prefers being alone.", "c": "Introvert", "d": ["Extrovert", "Ambivert", "Egotist"], "e": "An introvert is a shy, reticent person who prefers solitary activities and focuses on internal thoughts and feelings.", "s": "'Intro-' (inward) + 'vert' (turn)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who always looks at the bright side of things.", "c": "Optimist", "d": ["Pessimist", "Fatalist", "Realist"], "e": "An optimist is a person who tends to be hopeful and confident about the future or the success of something.", "s": "'Optimus' = best; contrast with 'pessimist' (worst)."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: One who is indifferent to pleasure or pain and endures hardship without complaint.", "c": "Stoic", "d": ["Cynic", "Epicure", "Martyr"], "e": "A stoic is a person who can endure pain, grief, or hardship without showing feelings or complaining.", "s": "Stoic = calm endurance; epicure = pleasure-seeker."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who believes that everybody is selfish and motivated by self-interest.", "c": "Cynic", "d": ["Skeptic", "Stoic", "Sycophant"], "e": "A cynic is a person who believes that people are motivated purely by self-interest rather than acting for honourable reasons.", "s": "A cynic doubts human sincerity; a sycophant flatters."}, {"t": "Personality Traits", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who is excessively obsessed with themselves and their appearance.", "c": "Narcissist", "d": ["Altruist", "Pessimist", "Hypochondriac"], "e": "A narcissist is a person who has an excessive interest in or admiration of themselves and their own appearance.", "s": "Named after Narcissus in Greek mythology, who fell in love with his reflection."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: The murder of a king or queen.", "c": "Regicide", "d": ["Homicide", "Patricide", "Genocide"], "e": "Regicide is the action of killing a king or monarch.", "s": "Root 'reg-' (king, as in regal) + '-cide' (killing)."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: The killing of one's own brother.", "c": "Fratricide", "d": ["Sororicide", "Patricide", "Uxoricide"], "e": "Fratricide is the killing of one's brother (or sister in broader legal/general usage, specifically brother).", "s": "Root 'frater' = brother + '-cide' = killing."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: The killing of one's own mother.", "c": "Matricide", "d": ["Patricide", "Mariticide", "Uxoricide"], "e": "Matricide is the act of killing one's own mother.", "s": "'Mater' = mother + '-cide' = killing; 'uxor' = wife."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: The deliberate killing of a whole race, nation, or ethnic group.", "c": "Genocide", "d": ["Homicide", "Massacre", "Infanticide"], "e": "Genocide is the deliberate killing of a large number of people from a particular nation, race, or ethnic group with the aim of destroying that group.", "s": "Root 'genos' (race/tribe) + '-cide' (killing)."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: The killing of an infant or newborn child.", "c": "Infanticide", "d": ["Foeticide", "Filicide", "Parricide"], "e": "Infanticide is the crime of killing an infant or young child.", "s": "'Infant' + '-cide' (killing); 'filicide' is killing one's own child of any age."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: An extreme fear of confined or enclosed spaces.", "c": "Claustrophobia", "d": ["Agoraphobia", "Acrophobia", "Nyctophobia"], "e": "Claustrophobia is an extreme or irrational fear of confined, narrow, or enclosed places.", "s": "Root 'claustrum' (closed place) + 'phobia' (fear)."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: An extreme or irrational fear of heights.", "c": "Acrophobia", "d": ["Claustrophobia", "Aerophobia", "Vertigo"], "e": "Acrophobia is an extreme or irrational fear of heights.", "s": "Root 'acro' (high/peak) + 'phobia' (fear); aerophobia is fear of flying."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: An extreme fear of water.", "c": "Hydrophobia", "d": ["Photophobia", "Pyrophobia", "Hemophobia"], "e": "Hydrophobia is an extreme or irrational fear of water (also historically associated with rabies).", "s": "Root 'hydro' = water + 'phobia' = fear."}, {"t": "Killings & Phobias", "q": "Select the option that can be used as a one-word substitute for the given group of words: Fear or hatred of foreigners and strangers.", "c": "Xenophobia", "d": ["Homophobia", "Zoophobia", "Agoraphobia"], "e": "Xenophobia is the dislike of or prejudice against people from other countries or strangers.", "s": "Root 'xeno' = stranger/foreign + 'phobia' = fear."}, {"t": "Manias", "q": "Select the option that can be used as a one-word substitute for the given group of words: An irresistible impulse or obsession to steal.", "c": "Kleptomania", "d": ["Pyromania", "Dipsomania", "Megalomania"], "e": "Kleptomania is a recurrent, irresistible urge to steal items that are generally not needed for personal use or monetary value.", "s": "'Klepto' (steal) + 'mania' (obsession/madness)."}, {"t": "Manias", "q": "Select the option that can be used as a one-word substitute for the given group of words: An obsessive desire to set things on fire.", "c": "Pyromania", "d": ["Kleptomania", "Bibliomania", "Mythomania"], "e": "Pyromania is an obsessive, uncontrollable desire to start fires.", "s": "Root 'pyro' = fire + 'mania' = madness/obsession."}, {"t": "Manias", "q": "Select the option that can be used as a one-word substitute for the given group of words: An obsessive craze for collecting books.", "c": "Bibliomania", "d": ["Bibliophile", "Logomania", "Graphomania"], "e": "Bibliomania is an obsessive enthusiasm for collecting and possessing books, whereas a bibliophile is simply a lover of books.", "s": "'Biblio' (book) + 'mania' (obsession). Note: '-phile' = lover, '-mania' = craze."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Lasting for a very short time.", "c": "Ephemeral", "d": ["Eternal", "Perpetual", "Enduring"], "e": "Ephemeral means lasting for a very short time, often just a day or a brief moment.", "s": "Think of 'ephemera' (short-lived things); opposite of eternal."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Present, appearing, or found everywhere.", "c": "Ubiquitous", "d": ["Scarce", "Sporadic", "Exclusive"], "e": "Ubiquitous means present, appearing, or found everywhere at the same time.", "s": "Root 'ubique' = everywhere (similar to omnipresent)."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: A remedy or cure for all diseases or difficulties.", "c": "Panacea", "d": ["Placebo", "Antidote", "Elixir"], "e": "A panacea is a supposed solution or remedy for all difficulties, problems, or diseases.", "s": "'Pan-' (all) + 'akos' (cure) = cure-all."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Occurring, awarded, or published after the death of its originator.", "c": "Posthumous", "d": ["Anonymous", "Contemporary", "Antiquated"], "e": "Posthumous describes something occurring, awarded, or published after the death of the person concerned.", "s": "'Post' (after) + 'humus' (ground/burial) = after death."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Persons living at the same time.", "c": "Contemporaries", "d": ["Predecessors", "Successors", "Ancestors"], "e": "Contemporaries are people or things living or existing at the same period of time.", "s": "'Con-' (together/same) + 'tempor' (time)."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: One who is incapable of making mistakes.", "c": "Infallible", "d": ["Incorrigible", "Inevitable", "Invincible"], "e": "Infallible means incapable of making mistakes or being wrong.", "s": "'In-' (not) + 'fallible' (capable of failing/erring)."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Handwriting that is impossible or too unclear to read.", "c": "Illegible", "d": ["Ineligible", "Illiterate", "Inaudible"], "e": "Illegible means handwriting or print that is not clear enough to be read.", "s": "'Il-' (not) + 'legible' (readable). Do not confuse with 'ineligible' (unqualified)."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Capable of being understood in more than one way; having double meaning.", "c": "Ambiguous", "d": ["Explicit", "Lucid", "Unanimous"], "e": "Ambiguous means open to more than one interpretation and therefore unclear or inexact.", "s": "'Ambi-' (both/two) + 'agere' (drive) = two possible meanings."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: A person who walks in their sleep.", "c": "Somnambulist", "d": ["Somniloquist", "Insomniac", "Funambulist"], "e": "A somnambulist is a person who walks around while asleep.", "s": "'Somnus' (sleep) + 'ambul' (walk); 'somniloquist' talks in sleep."}, {"t": "General OWS", "q": "Select the option that can be used as a one-word substitute for the given group of words: Words inscribed on a tombstone in memory of the deceased.", "c": "Epitaph", "d": ["Epigram", "Epilogue", "Obituary"], "e": "An epitaph is an inscription written on a tombstone in memory of the person buried there.", "s": "'Epi-' (upon) + 'taphos' (tomb) = on a tomb."}]}, {"id": "ch-eng-voice-narration", "title": "Voice & Direct-Indirect Speech", "subtitle": "Active-Passive Transformation & Narration Rules", "questions": [{"t": "Voice: Simple Present", "q": "Select the option that expresses the given sentence in passive voice: He plays cricket every Sunday.", "c": "Cricket is played by him every Sunday.", "d": ["Cricket was played by him every Sunday.", "Cricket is being played by him every Sunday.", "Cricket has been played by him every Sunday."], "e": "Simple Present active ('plays') changes to 'is/am/are + V3' ('is played') in passive voice.", "s": "Simple Present Passive: Object + is/am/are + V3 + by + Subject."}, {"t": "Voice: Present Continuous", "q": "Select the option that expresses the given sentence in passive voice: Riya is singing a melodious song.", "c": "A melodious song is being sung by Riya.", "d": ["A melodious song is sung by Riya.", "A melodious song was being sung by Riya.", "A melodious song has been sung by Riya."], "e": "Present Continuous active ('is singing') changes to 'is/am/are + being + V3' ('is being sung') in passive voice.", "s": "Continuous tense always adds 'being' before V3 in passive voice."}, {"t": "Voice: Present Perfect", "q": "Select the option that expresses the given sentence in passive voice: The students have submitted the assignment.", "c": "The assignment has been submitted by the students.", "d": ["The assignment had been submitted by the students.", "The assignment was submitted by the students.", "The assignment is being submitted by the students."], "e": "Present Perfect active ('have submitted') changes to 'has/have + been + V3'. Since 'the assignment' is singular, 'has been submitted' is correct.", "s": "Perfect tense adds 'been' before V3; match 'has/have' to the new singular subject."}, {"t": "Voice: Simple Past", "q": "Select the option that expresses the given sentence in passive voice: The children ate the entire cake.", "c": "The entire cake was eaten by the children.", "d": ["The entire cake is eaten by the children.", "The entire cake had been eaten by the children.", "The entire cake was being eaten by the children."], "e": "Simple Past active ('ate') changes to 'was/were + V3' ('was eaten') in passive voice.", "s": "Simple Past Passive: was/were + V3 (never 'had been' or 'was being')."}, {"t": "Voice: Past Continuous", "q": "Select the option that expresses the given sentence in passive voice: The workers were painting the wall.", "c": "The wall was being painted by the workers.", "d": ["The wall was painted by the workers.", "The wall is being painted by the workers.", "The wall had been painted by the workers."], "e": "Past Continuous active ('were painting') changes to 'was/were + being + V3'. With singular 'the wall', it becomes 'was being painted'.", "s": "Keep the past tense and insert 'being' + V3: was being painted."}, {"t": "Voice: Past Perfect", "q": "Select the option that expresses the given sentence in passive voice: The manager had signed the documents before the meeting.", "c": "The documents had been signed by the manager before the meeting.", "d": ["The documents were signed by the manager before the meeting.", "The documents have been signed by the manager before the meeting.", "The documents had signed by the manager before the meeting."], "e": "Past Perfect active ('had signed') changes to 'had + been + V3' ('had been signed') in passive voice.", "s": "Past Perfect Passive: had + been + V3."}, {"t": "Voice: Simple Future", "q": "Select the option that expresses the given sentence in passive voice: The board will announce the results tomorrow.", "c": "The results will be announced by the board tomorrow.", "d": ["The results would be announced by the board tomorrow.", "The results will have been announced by the board tomorrow.", "The results are announced by the board tomorrow."], "e": "Simple Future active ('will announce') changes to 'will + be + V3' ('will be announced'); 'will' does not change to 'would' in voice transformation.", "s": "In Voice, tenses never shift (will stays will); only add 'be + V3'."}, {"t": "Voice: Future Perfect", "q": "Select the option that expresses the given sentence in passive voice: The engineers will have built the bridge by next year.", "c": "The bridge will have been built by the engineers by next year.", "d": ["The bridge will be built by the engineers by next year.", "The bridge would have been built by the engineers by next year.", "The bridge has been built by the engineers by next year."], "e": "Future Perfect active ('will have built') changes to 'will have been + V3' in passive voice.", "s": "Future Perfect Passive: will/shall + have been + V3."}, {"t": "Voice: Modals", "q": "Select the option that expresses the given sentence in passive voice: Every citizen must obey traffic rules.", "c": "Traffic rules must be obeyed by every citizen.", "d": ["Traffic rules must have been obeyed by every citizen.", "Traffic rules should be obeyed by every citizen.", "Traffic rules are obeyed by every citizen."], "e": "Modal verbs ('must + V1') change to 'must + be + V3' in passive voice without changing the modal itself.", "s": "Modal Passive: keep the same modal + be + V3."}, {"t": "Voice: Past Modals", "q": "Select the option that expresses the given sentence in passive voice: Our team could have won the match.", "c": "The match could have been won by our team.", "d": ["The match could be won by our team.", "The match can have been won by our team.", "The match would have been won by our team."], "e": "Past modal 'could have + V3' transforms into 'could have been + V3' in passive voice.", "s": "Modal Perfect Passive: modal + have been + V3."}, {"t": "Voice: Imperative", "q": "Select the option that expresses the given sentence in passive voice: Lock the main gate immediately.", "c": "Let the main gate be locked immediately.", "d": ["Let the main gate locked immediately.", "The main gate should lock immediately.", "Let the main gate is locked immediately."], "e": "An imperative command with an object ('Lock the main gate') takes the passive form 'Let + object + be + V3'.", "s": "Imperative Passive: Let + Object + be + V3."}, {"t": "Voice: Imperative Request", "q": "Select the option that expresses the given sentence in passive voice: Please lend me your dictionary.", "c": "You are requested to lend me your dictionary.", "d": ["You are ordered to lend me your dictionary.", "Let your dictionary be lent to me.", "You were requested to lend me your dictionary."], "e": "Imperative sentences starting with 'Please' or 'Kindly' change to 'You are requested to + V1...' in passive voice.", "s": "'Please' -> 'You are requested to' (present tense)."}, {"t": "Voice: Imperative Advice", "q": "Select the option that expresses the given sentence in passive voice: Respect your elders.", "c": "Your elders should be respected by you.", "d": ["Let your elders respected.", "Your elders must be respected.", "Your elders are respected by you."], "e": "Imperative sentences expressing moral duty or advice take 'should be + V3' in passive voice (or 'You are advised to...').", "s": "Moral duty imperatives use 'should be + V3' in SSC passive options."}, {"t": "Voice: Interrogative Who", "q": "Select the option that expresses the given sentence in passive voice: Who broke this glass?", "c": "By whom was this glass broken?", "d": ["By whom this glass was broken?", "Who was this glass broken by?", "By whom is this glass broken?"], "e": "Interrogative 'Who' changes to 'By whom' followed by the auxiliary verb ('was'), subject ('this glass'), and V3 ('broken'). Note that the helping verb must precede the subject in a question.", "s": "'Who + V2 + Obj?' -> 'By whom + was/were + Obj + V3?'"}, {"t": "Voice: Interrogative Whom", "q": "Select the option that expresses the given sentence in passive voice: Whom did you invite to the ceremony?", "c": "Who was invited to the ceremony by you?", "d": ["Whom was invited to the ceremony by you?", "By whom were you invited to the ceremony?", "Who had been invited to the ceremony by you?"], "e": "Interrogative 'Whom' (object) becomes 'Who' (subject) in passive voice: 'Who + was + V3 + ... + by you?'.", "s": "'Whom + did + S + V1?' -> 'Who + was/were + V3 + by + S?'"}, {"t": "Voice: Yes/No Interrogative", "q": "Select the option that expresses the given sentence in passive voice: Did she complete the report on time?", "c": "Was the report completed on time by her?", "d": ["Did the report completed on time by her?", "Is the report completed on time by her?", "Had the report been completed on time by her?"], "e": "Yes/No Simple Past question ('Did + S + V1...?') converts to 'Was/Were + Object + V3 + by + S?'.", "s": "Keep interrogative word order: Was/Were + Subject + V3."}, {"t": "Voice: Double Object", "q": "Select the option that expresses the given sentence in passive voice: My grandfather gave me a silver watch.", "c": "I was given a silver watch by my grandfather.", "d": ["I am given a silver watch by my grandfather.", "A silver watch is given to me by my grandfather.", "I had been given a silver watch by my grandfather."], "e": "With ditransitive verbs ('gave'), either the indirect object ('I') or direct object ('a silver watch') can become the passive subject; in Simple Past it takes 'was + V3'.", "s": "Double object: keep Simple Past ('gave' -> 'was given'). Eliminate present/past perfect options."}, {"t": "Voice: Fixed Preposition", "q": "Select the option that expresses the given sentence in passive voice: I know her uncle well.", "c": "Her uncle is well known to me.", "d": ["Her uncle is well known by me.", "Her uncle was well known to me.", "Her uncle is being well known to me."], "e": "The verb 'know' takes the fixed preposition 'to' instead of 'by' in passive voice ('known to').", "s": "Fixed passive preposition: 'known to', NOT 'known by'."}, {"t": "Voice: Fixed Preposition", "q": "Select the option that expresses the given sentence in passive voice: His sudden resignation surprised us.", "c": "We were surprised at his sudden resignation.", "d": ["We were surprised by his sudden resignation.", "We were surprised with his sudden resignation.", "We are surprised at his sudden resignation."], "e": "In passive voice, verbs expressing emotion or reaction such as 'surprised', 'astonished', and 'amazed' take 'at' rather than 'by'.", "s": "Fixed passive preposition: 'surprised at', 'astonished at', 'amazed at'."}, {"t": "Voice: Infinitive", "q": "Select the option that expresses the given sentence in passive voice: It is time to close the shop.", "c": "It is time for the shop to be closed.", "d": ["It was time for the shop to be closed.", "It is time for the shop to close.", "It is time that the shop was closed."], "e": "Sentences structured as 'It is time to + V1 + Object' change in passive to 'It is time for + Object + to be + V3'.", "s": "Pattern: It is time + to V1 + Obj -> It is time + for + Obj + to be + V3."}, {"t": "Voice: Quasi-Passive", "q": "Select the option that expresses the given sentence in passive voice: Quinine tastes bitter.", "c": "Quinine is bitter when it is tasted.", "d": ["Quinine is tasted bitter.", "Quinine was bitter when tasted.", "Quinine is bitter when tasting."], "e": "Quasi-passive verbs like 'taste', 'smell', and 'feel' followed by an adjective take the passive pattern 'Subject + is/are + Adjective + when (it is/they are) + V3'.", "s": "Quasi-passive rule: Subject + be + Adj + when + pronoun + be + V3."}, {"t": "Voice: Passive to Active", "q": "Select the option that expresses the given sentence in active voice: My wallet was stolen in the crowded bus.", "c": "Someone stole my wallet in the crowded bus.", "d": ["Someone steals my wallet in the crowded bus.", "Someone had stolen my wallet in the crowded bus.", "My wallet stole someone in the crowded bus."], "e": "When converting Simple Past passive ('was stolen') with an implied agent back to active voice, we supply an indefinite subject like 'Someone' with V2 ('stole').", "s": "Simple Past Passive ('was + V3') -> Active V2 ('stole') with implied 'Someone'."}, {"t": "Voice: Passive to Active", "q": "Select the option that expresses the given sentence in active voice: The old car is being repaired by the mechanic.", "c": "The mechanic is repairing the old car.", "d": ["The mechanic repairs the old car.", "The mechanic was repairing the old car.", "The mechanic has repaired the old car."], "e": "Present Continuous passive ('is being repaired') reverts to Present Continuous active ('is repairing').", "s": "Drop 'being' and return to 'is/am/are + V-ing'."}, {"t": "Voice: Passive to Active", "q": "Select the option that expresses the given sentence in active voice: The proposal has been rejected by the committee.", "c": "The committee has rejected the proposal.", "d": ["The committee had rejected the proposal.", "The committee rejected the proposal.", "The committee is rejecting the proposal."], "e": "Present Perfect passive ('has been rejected') converts back to Present Perfect active ('has rejected').", "s": "Drop 'been' -> Present Perfect Active ('has/have + V3')."}, {"t": "Voice: Passive to Active", "q": "Select the option that expresses the given sentence in active voice: Let the poor not be insulted.", "c": "Do not insult the poor.", "d": ["Let not insult the poor.", "You do not insult the poor.", "Did not insult the poor."], "e": "A negative imperative passive ('Let the poor not be insulted') converts back to the active negative imperative 'Do not + V1 + Object'.", "s": "'Let + Obj + not be + V3' <-> 'Do not + V1 + Obj'."}, {"t": "Voice: Passive to Active", "q": "Select the option that expresses the given sentence in active voice: By whom were you taught French?", "c": "Who taught you French?", "d": ["Whom taught you French?", "Who teaches you French?", "Who had taught you French?"], "e": "'By whom were you taught...' (Simple Past passive) reverts to 'Who + V2 + Object?' ('Who taught you French?').", "s": "'By whom + was/were + S + V3' <-> 'Who + V2 + Obj'."}, {"t": "Narration: Simple Present", "q": "Select the option that expresses the given sentence in indirect speech: She said, \"I like classical music.\"", "c": "She said that she liked classical music.", "d": ["She said that she likes classical music.", "She told that she liked classical music.", "She said that I liked classical music."], "e": "With a past reporting verb ('said'), Simple Present ('like') shifts to Simple Past ('liked'), and 'I' changes to 'she'. Note that 'told' requires an object and cannot be used without one.", "s": "Past reporting verb: V1 -> V2; 'said' without object never becomes 'told'."}, {"t": "Narration: Present Continuous", "q": "Select the option that expresses the given sentence in indirect speech: Rahul said to me, \"I am preparing for the exam.\"", "c": "Rahul told me that he was preparing for the exam.", "d": ["Rahul told me that he is preparing for the exam.", "Rahul said me that he was preparing for the exam.", "Rahul told me that he had been preparing for the exam."], "e": "'said to me' changes to 'told me', and Present Continuous ('am preparing') backshifts to Past Continuous ('was preparing').", "s": "Present Continuous -> Past Continuous; 'said to' -> 'told'."}, {"t": "Narration: Present Perfect", "q": "Select the option that expresses the given sentence in indirect speech: Anita said, \"I have finished my work.\"", "c": "Anita said that she had finished her work.", "d": ["Anita said that she has finished her work.", "Anita said that she finished her work.", "Anita asked that she had finished her work."], "e": "Present Perfect ('have finished') backshifts to Past Perfect ('had finished') when the reporting verb is in the past tense.", "s": "Present Perfect ('have/has + V3') -> Past Perfect ('had + V3')."}, {"t": "Narration: Simple Past", "q": "Select the option that expresses the given sentence in indirect speech: He said, \"I bought a new laptop.\"", "c": "He said that he had bought a new laptop.", "d": ["He said that he bought a new laptop.", "He said that he has bought a new laptop.", "He said that he was buying a new laptop."], "e": "Simple Past ('bought') in direct speech changes to Past Perfect ('had bought') in indirect speech.", "s": "Simple Past (V2) -> Past Perfect (had + V3) in indirect speech."}, {"t": "Narration: Past Continuous", "q": "Select the option that expresses the given sentence in indirect speech: They said, \"We were waiting for the train.\"", "c": "They said that they had been waiting for the train.", "d": ["They said that they were waiting for the train.", "They said that they have been waiting for the train.", "They said that they waited for the train."], "e": "Past Continuous ('were waiting') changes to Past Perfect Continuous ('had been waiting') in indirect speech.", "s": "Past Continuous -> Past Perfect Continuous ('had been + V-ing')."}, {"t": "Narration: Future Tense", "q": "Select the option that expresses the given sentence in indirect speech: Mohan said to his friend, \"I will visit Delhi soon.\"", "c": "Mohan told his friend that he would visit Delhi soon.", "d": ["Mohan told his friend that he will visit Delhi soon.", "Mohan told to his friend that he would visit Delhi soon.", "Mohan told his friend that he would visited Delhi soon."], "e": "'said to' becomes 'told' (never 'told to'), and 'will' changes to 'would'. Pronoun 'I' becomes 'he'.", "s": "'will' -> 'would' + V1; never use 'to' after 'told'."}, {"t": "Narration: Modals & Demonstratives", "q": "Select the option that expresses the given sentence in indirect speech: Priya said, \"I can solve this puzzle easily.\"", "c": "Priya said that she could solve that puzzle easily.", "d": ["Priya said that she can solve this puzzle easily.", "Priya said that she could solve this puzzle easily.", "Priya said that she may solve that puzzle easily."], "e": "In indirect speech with a past reporting verb, 'can' shifts to 'could' and 'this' shifts to 'that'.", "s": "Shifts: 'can' -> 'could', 'this' -> 'that'."}, {"t": "Narration: Universal Truth", "q": "Select the option that expresses the given sentence in indirect speech: The teacher said, \"The sun rises in the east.\"", "c": "The teacher said that the sun rises in the east.", "d": ["The teacher said that the sun rose in the east.", "The teacher told that the sun rises in the east.", "The teacher said that the sun had risen in the east."], "e": "Universal truths and scientific facts remain in the Simple Present tense in indirect speech even when the reporting verb is in the past.", "s": "Universal truth = NO tense backshift. Keep 'rises'."}, {"t": "Narration: Proverbs", "q": "Select the option that expresses the given sentence in indirect speech: My father said, \"Honesty is the best policy.\"", "c": "My father said that honesty is the best policy.", "d": ["My father said that honesty was the best policy.", "My father said that honesty had been the best policy.", "My father told that honesty is the best policy."], "e": "Proverbs and habitual truths retain their Simple Present tense ('is') in indirect speech.", "s": "Proverbs never change tense in indirect speech."}, {"t": "Narration: Present Reporting Verb", "q": "Select the option that expresses the given sentence in indirect speech: She says, \"I am very happy today.\"", "c": "She says that she is very happy today.", "d": ["She says that she was very happy today.", "She said that she was very happy that day.", "She says that she was very happy that day."], "e": "When the reporting verb is in the Present or Future tense ('says'), the tense and time words inside the reported speech do NOT change.", "s": "Present reporting verb ('says') = no backshift of verb or 'today'."}, {"t": "Narration: Time Shifts", "q": "Select the option that expresses the given sentence in indirect speech: He said to me, \"I met my cousin yesterday.\"", "c": "He told me that he had met his cousin the previous day.", "d": ["He told me that he met his cousin yesterday.", "He told me that he had met his cousin yesterday.", "He asked me that he had met his cousin the previous day."], "e": "Simple Past ('met') shifts to Past Perfect ('had met'), and 'yesterday' changes to 'the previous day' (or 'the day before').", "s": "'V2' -> 'had + V3'; 'yesterday' -> 'the previous day'."}, {"t": "Narration: Time & Place Shifts", "q": "Select the option that expresses the given sentence in indirect speech: Sita said, \"I shall go here tomorrow.\"", "c": "Sita said that she would go there the next day.", "d": ["Sita said that she would go here tomorrow.", "Sita said that she will go there the next day.", "Sita said that she would go there yesterday."], "e": "In indirect speech, 'shall/will' changes to 'would' (matching 'she'), 'here' changes to 'there', and 'tomorrow' changes to 'the next day'.", "s": "Shifts: 'shall' (with I -> she) -> 'would', 'here' -> 'there', 'tomorrow' -> 'the next day'."}, {"t": "Narration: Yes/No Interrogative", "q": "Select the option that expresses the given sentence in indirect speech: The policeman said to the boy, \"Do you know the way to the station?\"", "c": "The policeman asked the boy if he knew the way to the station.", "d": ["The policeman asked the boy that if he knew the way to the station.", "The policeman asked the boy did he know the way to the station.", "The policeman told the boy whether he knows the way to the station."], "e": "Yes/No questions take 'if' or 'whether' (never 'that if'), use statement word order (subject before verb), and shift 'know' to 'knew'.", "s": "Yes/No question: 'asked' + 'if/whether' + Subject + Verb (no 'that')."}, {"t": "Narration: Wh-Interrogative", "q": "Select the option that expresses the given sentence in indirect speech: She said to me, \"Where do you live?\"", "c": "She asked me where I lived.", "d": ["She asked me where did I live.", "She asked me that where I lived.", "She asked me where I live."], "e": "For Wh-questions, the Wh-word itself acts as the connector (no 'that'), and the clause follows assertive word order ('where I lived', not 'where did I live').", "s": "Wh-question rule: no 'that', drop 'do/did', put Subject before Verb."}, {"t": "Narration: Imperative Command", "q": "Select the option that expresses the given sentence in indirect speech: The captain said to the soldiers, \"March forward.\"", "c": "The captain ordered the soldiers to march forward.", "d": ["The captain ordered the soldiers that they march forward.", "The captain said to the soldiers to march forward.", "The captain requested the soldiers to march forward."], "e": "An imperative command changes 'said to' to 'ordered' or 'commanded' and links the verb with the infinitive 'to + V1'.", "s": "Imperative command: ordered + object + to + V1."}, {"t": "Narration: Negative Imperative", "q": "Select the option that expresses the given sentence in indirect speech: The doctor said to the patient, \"Do not eat junk food.\"", "c": "The doctor advised the patient not to eat junk food.", "d": ["The doctor advised the patient to not eat junk food.", "The doctor forbade the patient not to eat junk food.", "The doctor said the patient do not eat junk food."], "e": "Negative imperatives change to 'advised/ordered + object + not to + V1'. Note that 'forbade ... not to' is wrong because 'forbade' is already negative.", "s": "Use 'not to + V1' (never 'forbade ... not to')."}, {"t": "Narration: Proposal (Let us)", "q": "Select the option that expresses the given sentence in indirect speech: Ravi said to his friends, \"Let us go for a picnic.\"", "c": "Ravi suggested to his friends that they should go for a picnic.", "d": ["Ravi ordered his friends that they go for a picnic.", "Ravi asked his friends to let them go for a picnic.", "Ravi told his friends that we should go for a picnic."], "e": "Sentences starting with 'Let us' expressing a proposal change to 'suggested/proposed to + object + that they/we should + V1'.", "s": "'Let us' proposal -> 'proposed/suggested that they should'."}, {"t": "Narration: Exclamatory Joy", "q": "Select the option that expresses the given sentence in indirect speech: The players said, \"Hurrah! We have won the tournament.\"", "c": "The players exclaimed with joy that they had won the tournament.", "d": ["The players exclaimed with joy that they won the tournament.", "The players said with joy that we had won the tournament.", "The players exclaimed with sorrow that they had won the tournament."], "e": "'Hurrah!' expresses joy ('exclaimed with joy'), and Simple Past ('won') shifts to Past Perfect ('had won').", "s": "'Hurrah!' -> 'exclaimed with joy'; 'have won' -> 'had won'."}, {"t": "Narration: Exclamatory Sorrow", "q": "Select the option that expresses the given sentence in indirect speech: The old woman said, \"Alas! I am ruined.\"", "c": "The old woman exclaimed with sorrow that she was ruined.", "d": ["The old woman exclaimed with sorrow that she is ruined.", "The old woman told with sorrow that I was ruined.", "The old woman exclaimed with surprise that she was ruined."], "e": "'Alas!' denotes grief ('exclaimed with sorrow'), and 'am' shifts to 'was' in indirect speech.", "s": "'Alas!' -> 'exclaimed with sorrow'; 'am' -> 'was'."}, {"t": "Narration: Exclamatory What/How", "q": "Select the option that expresses the given sentence in indirect speech: He said, \"What a beautiful painting it is!\"", "c": "He exclaimed that it was a very beautiful painting.", "d": ["He asked what a beautiful painting it was.", "He exclaimed that what a beautiful painting it was.", "He said that it is a very beautiful painting."], "e": "Exclamatory 'What a + Adj + Noun!' converts to an assertive clause using 'very' ('it was a very beautiful painting') and drops 'what'.", "s": "Drop 'what/how' and insert 'very/great' in assertive order."}, {"t": "Narration: Optative Sentence", "q": "Select the option that expresses the given sentence in indirect speech: The saint said to me, \"May God bless you!\"", "c": "The saint prayed that God might bless me.", "d": ["The saint told that God may bless me.", "The saint prayed that God will bless me.", "The saint wished that might God bless me."], "e": "Optative sentences beginning with 'May' change to 'prayed/wished that + Subject + might + V1'.", "s": "Optative rule: 'prayed/wished that + Subject + might + V1'."}, {"t": "Narration: Indirect to Direct", "q": "Select the option that expresses the given sentence in direct speech: Karan told me that he had visited Goa the previous week.", "c": "Karan said to me, \"I visited Goa last week.\"", "d": ["Karan said to me, \"I have visited Goa last week.\"", "Karan said to me, \"I visited Goa the previous week.\"", "Karan asked me, \"Did I visit Goa last week?\""], "e": "When converting back to direct speech, Past Perfect ('had visited') reverts to Simple Past ('visited') and 'the previous week' reverts to 'last week'.", "s": "Reverse shift: 'the previous week' -> 'last week', 'had + V3' -> 'V2'."}, {"t": "Narration: Indirect to Direct", "q": "Select the option that expresses the given sentence in direct speech: The teacher asked the student why he was late.", "c": "The teacher said to the student, \"Why are you late?\"", "d": ["The teacher said to the student, \"Why were you late?\"", "The teacher said to the student, \"Why you are late?\"", "The teacher told the student, \"Why are you late?\""], "e": "Indirect Past Continuous ('was late' -> simple past state 'was' reverses to 'is/are') in a question reverts to 'Why are you late?' with interrogative inversion.", "s": "Reverse Wh-question: restore 'are you' before the adjective and use 'said to'."}, {"t": "Narration: Indirect to Direct", "q": "Select the option that expresses the given sentence in direct speech: She asked him whether he had completed the task.", "c": "She said to him, \"Have you completed the task?\"", "d": ["She said to him, \"Had you completed the task?\"", "She said to him, \"Did you completed the task?\"", "She said to him, \"Have you complete the task?\""], "e": "Indirect 'if he had completed' reverts to a Present Perfect Yes/No question: 'Have you completed...?'. Note that 'Did you completed' is ungrammatical.", "s": "'whether + S + had + V3' -> '\"Have/Did + S + ...?\"'; check correct verb form!"}]}, {"id": "ch-eng-misc", "title": "Fillers, Improvement, Jumbles & Spellings", "subtitle": "Cloze/Fillers, Sentence Improvement, PQRS Para Jumbles & Correctly/Incorrectly Spelt", "questions": [{"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: Every citizen must abide ______ the laws of the country.", "c": "by", "d": ["with", "to", "on"], "e": "The phrasal verb 'abide by' means to accept or act in accordance with a rule, decision, or agreement.", "s": "Fixed preposition: always 'abide BY' a rule or law."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: After a long trial, the accused was finally acquitted ______ all charges.", "c": "of", "d": ["from", "with", "for"], "e": "The verb 'acquit' takes the fixed preposition 'of' when stating the crime or charge a person is cleared of.", "s": "Fixed preposition: 'acquitted OF' charges, 'accused OF' a crime."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: He is averse ______ taking unnecessary financial risks.", "c": "to", "d": ["from", "with", "of"], "e": "The adjective 'averse' (meaning having a strong dislike of or opposition to) is always followed by the preposition 'to'.", "s": "Fixed preposition: 'averse TO' (also 'addicted to', 'prone to')."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: A peaceful environment is conducive ______ focused study.", "c": "to", "d": ["for", "with", "in"], "e": "'Conducive' means making a certain situation or outcome likely or possible, and it is always followed by 'to'.", "s": "Fixed preposition: 'conducive TO' (never 'for')."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: His speech was completely devoid ______ any logic or evidence.", "c": "of", "d": ["from", "with", "by"], "e": "The adjective 'devoid' (entirely lacking or free from) takes the fixed preposition 'of'.", "s": "Fixed preposition: 'devoid OF', 'deprived OF'."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: She remained indifferent ______ both praise and criticism.", "c": "to", "d": ["for", "from", "about"], "e": "'Indifferent' (having no particular interest or sympathy) is always followed by the preposition 'to'.", "s": "Fixed preposition: 'indifferent TO'."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: The manager insisted ______ seeing the original receipts before approving the claim.", "c": "on", "d": ["to", "for", "at"], "e": "The verb 'insist' takes the fixed preposition 'on' (or 'upon') when followed by a noun or gerund.", "s": "Fixed preposition: 'insist ON' + V-ing/noun."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: All visitors are requested to comply ______ the safety regulations inside the plant.", "c": "with", "d": ["to", "by", "for"], "e": "'Comply' means to act in accordance with a wish or command, and it takes the fixed preposition 'with'.", "s": "Contrast: 'comply WITH', 'abide BY', 'adhere TO'."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: Passengers are advised to refrain ______ leaning out of the moving train.", "c": "from", "d": ["to", "against", "of"], "e": "'Refrain' (to stop oneself from doing something) is always followed by the preposition 'from'.", "s": "Fixed preposition: 'refrain FROM', 'abstain FROM'."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: Coastal regions are often prone ______ severe cyclones during the monsoon.", "c": "to", "d": ["for", "with", "of"], "e": "'Prone' (likely or liable to suffer from or do something) takes the fixed preposition 'to'.", "s": "Fixed preposition: 'prone TO', 'vulnerable TO'."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: She is quite adept ______ handling complex negotiations under pressure.", "c": "at", "d": ["on", "for", "to"], "e": "'Adept' (very skilled or proficient) takes the preposition 'at' (or 'in') before a skill or activity.", "s": "Fixed preposition: 'adept AT' or 'good AT' + V-ing."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: He finally reconciled himself ______ the fact that he would have to start over.", "c": "to", "d": ["with", "for", "in"], "e": "'Reconcile oneself to' means to accept an unpleasant situation that cannot be changed. (Wait: 'reconcile with' is used for reconciling with a person.)", "s": "'Reconcile oneself TO' a situation; 'reconcile WITH' a person."}, {"t": "Fillers: Collocations", "q": "Fill in the blank with the most appropriate word: Since the system is automated, we can dispense ______ manual data entry.", "c": "with", "d": ["of", "from", "off"], "e": "The phrasal verb 'dispense with' means to manage without or get rid of something no longer needed.", "s": "Phrasal verb: 'dispense WITH' = do without."}, {"t": "Fillers: Collocations", "q": "Fill in the blank with the most appropriate word: I can personally vouch ______ his honesty and dedication to work.", "c": "for", "d": ["to", "on", "about"], "e": "'Vouch for' is a standard collocation meaning to assert or confirm the truth, reliability, or character of someone or something.", "s": "Fixed collocation: 'vouch FOR' someone's integrity."}, {"t": "Fillers: Fixed Prepositions", "q": "Fill in the blank with the most appropriate word: Deeply engrossed in her novel, she was completely oblivious ______ the noise outside.", "c": "of", "d": ["to", "from", "with"], "e": "The adjective 'oblivious' (unaware of or unconcerned about what is happening around one) takes 'of' (or 'to' in some contexts, though 'of' is standard in SSC; here 'to' is avoided by checking options—wait let's replace 'to' in distractors so there is zero ambiguity!). Let's use 'for', 'from', 'with' as distractors.", "s": "Fixed preposition: 'oblivious OF' (unaware of)."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: No sooner did the teacher enter the classroom [when the students stood up].", "c": "than the students stood up", "d": ["when the students stood up", "then the students stood up", "that the students stood up"], "e": "The correlative pair is always 'No sooner ... than' (never 'when' or 'then'). Note the inversion 'did the teacher enter' is already in the sentence.", "s": "Fixed pair: 'No sooner ... than'; 'Hardly/Scarcely ... when'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: Hardly had we stepped out of the house [than it started raining heavily].", "c": "when it started raining heavily", "d": ["than it started raining heavily", "then it started raining heavily", "that it started raining heavily"], "e": "'Hardly' and 'Scarcely' are always paired with 'when' (or 'before'), never with 'than'.", "s": "Fixed pair: 'Hardly/Scarcely ... when'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: Walk fast lest you [will miss the train].", "c": "should miss the train", "d": ["will miss the train", "would not miss the train", "may not miss the train"], "e": "The conjunction 'lest' (meaning 'for fear that') is always followed by 'should + V1' and never takes 'not', as 'lest' itself is negative.", "s": "Rule: 'Lest ... should' (never 'will/not')."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: One of the rarest books in the library [are missing from the shelf].", "c": "is missing from the shelf", "d": ["are missing from the shelf", "were missing from the shelf", "have been missing from the shelf"], "e": "The structure 'One of the + Plural Noun' always takes a Singular Verb because the head subject is 'One'.", "s": "'One of the + Plural Noun + Singular Verb'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: Neither the principal nor the students [has submitted their forms] on time.", "c": "have submitted their forms", "d": ["has submitted their forms", "has submitted his form", "was submitting their forms"], "e": "With 'Neither ... nor', the verb agrees with the nearer subject ('the students', plural), so 'have' is required.", "s": "Proximity rule for 'Neither... nor': verb matches the second/nearer subject."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: The manager, as well as his assistants, [are invited to the wedding].", "c": "is invited to the wedding", "d": ["are invited to the wedding", "were invited to the wedding", "have been invited to the wedding"], "e": "When two subjects are joined by 'as well as', 'along with', or 'together with', the verb agrees with the first subject ('The manager', singular).", "s": "'S1 + as well as + S2' -> verb agrees with S1."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: It is high time you [start preparing for the exam].", "c": "started preparing for the exam", "d": ["start preparing for the exam", "have started preparing for the exam", "will start preparing for the exam"], "e": "Expressions like 'It is time', 'It is high time', and 'It is about time' followed by a subject take the Simple Past (V2) verb to indicate urgency.", "s": "Rule: 'It is high time + Subject + V2 (Simple Past)'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: After joining the new firm, she gradually got used [to work late at night].", "c": "to working late at night", "d": ["to work late at night", "with working late at night", "for working late at night"], "e": "The phrase 'be/get used to' (meaning accustomed to) treats 'to' as a preposition, so it must be followed by a gerund (V-ing), not V1.", "s": "'Subject + be/get + used to + V-ing' (accustomed to)."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: [If I was a bird], I would fly across the mountains.", "c": "If I were a bird", "d": ["If I was a bird", "If I am a bird", "If I would be a bird"], "e": "Hypothetical or unreal conditional wishes take the subjunctive form 'were' for all subjects, including 'I' and 'he/she'.", "s": "Unreal conditional: always 'If I were', never 'If I was'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: They [are living in this city since] 2015.", "c": "have been living in this city since", "d": ["are living in this city since", "were living in this city for", "have been living in this city for"], "e": "'Since 2015' indicates a point of time in the past continuing to the present, which requires Present Perfect Continuous ('have been living') with 'since'.", "s": "Point of time -> 'since' + Present Perfect / Present Perfect Continuous."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: My grandmother always [prefers tea than coffee] in the evening.", "c": "prefers tea to coffee", "d": ["prefers tea than coffee", "prefers tea over than coffee", "is preferring tea than coffee"], "e": "'Prefer' takes the preposition 'to' when comparing two nouns/gerunds, never 'than'. Also, 'prefer' is a stative verb not normally used in continuous tenses.", "s": "Rule: 'prefer X TO Y' (like senior/junior/superior to)."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: The Ganga is [more sacred than any river] in India.", "c": "more sacred than any other river", "d": ["more sacred than any river", "most sacred than any other river", "more sacred to any other river"], "e": "When comparing one member of a group against all others in the same group, use 'any other + singular noun' after a comparative adjective to exclude the subject itself.", "s": "Same-group comparison: 'Comparative + than + ANY OTHER + singular noun'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: They launched the campaign [with a view to improve] rural literacy.", "c": "with a view to improving", "d": ["with a view to improve", "with a view for improving", "for a view to improve"], "e": "The idiomatic phrase 'with a view to' ends with a preposition 'to' and therefore takes a gerund (V-ing).", "s": "'With a view to' / 'look forward to' + V-ing (gerund)."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: [Despite of working very hard], he could not clear the interview.", "c": "Despite working very hard", "d": ["Despite of working very hard", "In spite working very hard", "Despite he worked very hard"], "e": "'Despite' never takes 'of' after it ('Despite' = 'In spite of'). It is followed directly by a noun or gerund.", "s": "Rule: 'Despite' (no 'of') = 'In spite of'."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence: She is not only a brilliant writer [and also an accomplished singer].", "c": "but also an accomplished singer", "d": ["and also an accomplished singer", "but an accomplished singer also", "as well as an accomplished singer"], "e": "The correlative conjunction 'Not only' must be paired with 'but also' and maintain parallel grammatical structure ('a brilliant writer' / 'an accomplished singer').", "s": "Fixed pair: 'Not only ... but also' with parallel noun phrases."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. This rapid shift has made everyday transactions faster and more transparent for millions of citizens.\nQ. Over the past decade, digital payments have transformed the way India conducts financial transactions.\nR. However, rising cyber fraud remains a significant concern for first-time smartphone users.\nS. Therefore, strengthening digital literacy is essential to sustain public trust in cashless systems.", "c": "QPRS", "d": ["PQRS", "QRPS", "SQPR"], "e": "Q introduces the main subject (digital payments in India). P links to Q via 'This rapid shift' and states the benefit. R contrasts/expands on challenges ('However, ...'), and S gives the concluding recommendation ('Therefore, ...').", "s": "Find the intro sentence (Q), follow 'This rapid shift' (P), contrast 'However' (R), conclude 'Therefore' (S)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. The success of that agitation firmly established his method of non-violent resistance in Indian politics.\nQ. Upon his arrival, he travelled extensively across the country and led the Champaran satyagraha for indigo farmers.\nR. Mahatma Gandhi returned to India from South Africa in January 1915.\nS. This movement demonstrated that peaceful protest could compel colonial authorities to address public grievances.", "c": "RQSP", "d": ["QRSP", "RSQP", "PRQS"], "e": "R introduces Mahatma Gandhi's early life and return to India. Q follows chronologically with 'Upon his arrival'. S uses 'This movement' to refer to the Champaran campaign in Q, and P summarizes its lasting impact.", "s": "Chronology: 1915 return (R) -> upon arrival/Champaran (Q) -> This movement (S) -> conclusion (P)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. Sleep is a vital biological process that allows the human brain and body to recover.\nQ. Such chronic deprivation can impair memory, weaken immunity, and increase stress levels.\nR. During these hours of rest, the brain consolidates memories and repairs cellular tissues.\nS. Yet, modern lifestyles and excessive screen time have severely reduced average sleep duration.", "c": "PRSQ", "d": ["PQRS", "RPSQ", "SPQR"], "e": "P defines sleep as a vital biological process. R explains what happens during sleep ('During these hours, ...'). S adds a contrast ('Yet, modern lifestyles...'), and Q states the negative consequence of that deprivation ('Such chronic deprivation...').", "s": "Definition (P) -> 'these hours' (R) -> 'Yet' contrast (S) -> 'Such deprivation' (Q)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. Hence, urban planners must prioritize green cover when designing modern cities.\nQ. In addition, tree-lined streets filter harmful air pollutants and reduce ambient noise.\nR. They absorb solar radiation and provide shade, significantly lowering summer temperatures.\nS. Planting trees in densely populated cities offers multiple environmental and health benefits.", "c": "SRQP", "d": ["PQRS", "QSRP", "RSQP"], "e": "S introduces the general topic of urban trees. R specifies their cooling benefit ('They absorb...'). Q adds another benefit ('In addition, ...'), and P concludes with a call to action ('Hence, urban planners...').", "s": "General intro (S) -> 'They' benefit 1 (R) -> 'In addition' benefit 2 (Q) -> 'Hence' conclusion (P)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. A large portion of these discarded plastics eventually washes into the world's oceans.\nQ. Single-use plastic pollution has emerged as one of the most pressing environmental crises today.\nR. To tackle this threat, several nations have begun banning non-biodegradable packaging.\nS. Marine creatures often mistake these fragments for food, leading to fatal blockages.", "c": "QPSR", "d": ["PQRS", "QRPS", "SPQR"], "e": "Q introduces plastic pollution as a global crisis. P links via 'These discarded plastics' ending up in oceans. S explains the harm to marine animals ('Marine creatures often mistake them...'), and R concludes with international efforts ('To tackle this threat, ...').", "s": "Crisis intro (Q) -> 'these plastics' (P) -> 'Marine creatures' (S) -> 'To tackle this' (R)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. His movable metal type allowed pages to be reproduced rapidly and accurately.\nQ. As a result, books became affordable, and literacy rates began to rise across Europe.\nR. In the fifteenth century, Johannes Gutenberg revolutionized communication by inventing the printing press.\nS. This spread of knowledge ultimately laid the foundation for the European Renaissance.", "c": "RPQS", "d": ["PQRS", "QRPS", "PRQS"], "e": "R introduces the invention of the printing press by Gutenberg. P details how it worked ('His movable metal type...'). Q states the effect ('As a result, books became affordable...'), and S concludes with its role in the Renaissance.", "s": "Invention (R) -> 'His' mechanism (P) -> 'As a result' (Q) -> 'This spread' (S)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. These rains and melting glaciers feed perennial rivers like the Ganga and the Brahmaputra.\nQ. They block freezing Central Asian winds and trap moisture-laden monsoon clouds.\nR. Consequently, the Himalayan ecosystem sustains agriculture for hundreds of millions of people.\nS. The Himalayas play a crucial role in shaping the climate and hydrology of the Indian subcontinent.", "c": "SQPR", "d": ["PQRS", "QSRP", "RSQP"], "e": "S introduces the Himalayas as a vital mountain range. Q explains their role in blocking cold winds and causing monsoon rain. P links to 'These rains' feeding major rivers, and R concludes with their importance to agriculture ('Consequently, ...').", "s": "Topic (S) -> 'They' function (Q) -> 'These rains' (P) -> 'Consequently' (R)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. Effective time management is a crucial skill for students preparing for competitive examinations.\nQ. It begins with listing daily targets and prioritizing high-weightage topics.\nR. Breaking a vast syllabus into manageable weekly milestones prevents last-minute panic.\nS. Consistent adherence to such a schedule builds confidence and reduces exam anxiety.", "c": "PQRS", "d": ["QPRS", "RPQS", "SRQP"], "e": "P introduces time management for students. Q explains the first step (listing and prioritizing tasks). R adds the benefit of breaking large projects into smaller milestones, and S concludes that consistent adherence reduces exam anxiety.", "s": "Intro (P) -> 'It begins with' (Q) -> elaboration (R) -> 'such a schedule' (S)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. Protecting their habitats from excessive pesticide use is therefore vital for global food security.\nQ. Honeybees are among the most important pollinators in terrestrial ecosystems.\nR. Through this natural process, they support the reproduction of nearly one-third of the world's food crops.\nS. While collecting nectar from flowers, they inadvertently transfer pollen from one plant to another.", "c": "QSRP", "d": ["PQRS", "QRSP", "SQPR"], "e": "Q introduces honeybees as essential pollinators. S explains what happens during pollination ('While collecting nectar, ...'). R quantifies their impact on food crops, and P warns about declining bee populations ('Protecting their habitats...').", "s": "Subject (Q) -> process (S) -> 'this natural process' (R) -> 'therefore' conclusion (P)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. Tragically, a series of fires and conflicts destroyed the great institution over several centuries.\nQ. Because so many scrolls were lost, historians still wonder how much ancient knowledge vanished forever.\nR. The ancient Library of Alexandria in Egypt was one of the greatest centres of learning in the classical world.\nS. Scholars from across the Mediterranean travelled there to study hundreds of thousands of scrolls.", "c": "RSPQ", "d": ["PQRS", "SRPQ", "QRSP"], "e": "R introduces the library of Alexandria as an ancient centre of learning. S describes its collection ('Scholars from across...'). P mentions its tragic destruction over the centuries, and Q reflects on the loss of ancient knowledge ('Because so many...').", "s": "Intro (R) -> 'there' (S) -> destruction (P) -> aftermath 'so many scrolls' (Q)."}, {"t": "Para Jumbles (PQRS)", "q": "Rearrange the parts of the paragraph in correct order:\nP. Electric vehicles are increasingly viewed as a cleaner alternative to conventional petrol and diesel cars.\nQ. Expanding solar and wind power grids is thus key to making electric mobility truly green.\nR. However, their overall carbon footprint still depends on how the electricity charging them is generated.\nS. Unlike combustion engines, they produce zero tailpipe emissions during operation.", "c": "PSRQ", "d": ["PQRS", "SPRQ", "QRPS"], "e": "P introduces electric vehicles (EVs) as a cleaner alternative. S gives the immediate reason (zero tailpipe emissions). R qualifies this with a condition ('However, their overall carbon footprint...'), and Q concludes with the need to expand solar and wind power ('Expanding renewable energy...').", "s": "Intro (P) -> 'they' advantage (S) -> 'However' caveat (R) -> 'thus' solution (Q)."}, {"t": "Spellings", "q": "Select the INCORRECTLY spelt word.", "c": "Embarrasment", "d": ["Accommodation", "Bureaucracy", "Conscientious"], "e": "'Embarrasment' is misspelt; the correct spelling is 'Embarrassment' with double 'r' and double 's'. Accommodation, Bureaucracy, and Conscientious are spelt correctly.", "s": "Embarrassment has TWO r's and TWO s's (em-ba-rr-a-ss-ment)."}, {"t": "Spellings", "q": "Select the CORRECTLY spelt word.", "c": "Accommodate", "d": ["Acommodate", "Accomodate", "Acomodate"], "e": "The correct spelling is 'Accommodate', which contains double 'c' and double 'm'.", "s": "Accommodate = 2 c's + 2 m's ('cc', 'mm')."}, {"t": "Fillers", "q": "Select the most appropriate option to complete the sentence:\nHardly had the train left the station ______ it began to rain heavily.", "c": "when", "d": ["than", "then", "while"], "e": "The correlative pair for 'Hardly' or 'Scarcely' is 'when' (or 'before'), whereas 'than' is used with 'No sooner'.", "s": "Hardly / Scarcely + had + S + V3 ... when; No sooner + had + S + V3 ... than."}, {"t": "Fillers", "q": "Choose the most appropriate word to complete the given sentence:\nThe committee was divided in its opinion, so the members could not arrive at a ______ decision.", "c": "unanimous", "d": ["ambiguous", "anonymous", "ubiquitous"], "e": "'Unanimous' means held by everyone involved with full agreement, which contrasts with the committee being divided in its opinion.", "s": "uni- (one) + animus (mind) = unanimous (of one mind / full agreement)."}, {"t": "Cloze/Fillers", "q": "Select the correct option to complete the short passage:\nRegular exercise not only improves physical stamina but also ______ mental stress and enhances overall mood.", "c": "alleviates", "d": ["aggravates", "accumulates", "accelerates"], "e": "'Alleviates' means makes suffering or a problem like mental stress less severe, matching the positive context of improving stamina and mood.", "s": "Check tone + parallelism: positive effect -> singular verb reducing stress = alleviates."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to substitute the bracketed segment in the given sentence:\nIf I (was knowing) his address, I would have sent him the invitation card.", "c": "had known", "d": ["knew", "have known", "would know"], "e": "The main clause uses 'would have sent' (third conditional for an unreal past), which requires the past perfect tense ('had known') in the 'if'-clause.", "s": "3rd Conditional: If + S + had + V3, S + would have + V3."}, {"t": "Sentence Improvement", "q": "Improve the bracketed part of the sentence:\nNeither the manager nor his assistants (was) present at the client briefing yesterday.", "c": "were", "d": ["is", "has been", "No improvement required"], "e": "When subjects are joined by 'neither...nor', the verb agrees with the nearer subject ('assistants', plural), and 'yesterday' requires the past tense 'were'.", "s": "Neither A nor B -> verb agrees with B (Rule of Proximity) + past time marker."}, {"t": "Sentence Improvement", "q": "Select the most appropriate option to replace the bracketed segment:\nShe prefers classical music (than) modern pop songs.", "c": "to", "d": ["for", "from", "No improvement required"], "e": "The verb 'prefer' takes the fixed preposition 'to' when comparing two nouns or gerunds, never 'than'.", "s": "Prefer + Noun/Gerund + to + Noun/Gerund (never 'than')."}, {"t": "Para Jumbles", "q": "Rearrange the parts of the sentence in correct order (PQRS):\nP. who had worked tirelessly for months\nQ. the young scientist\nR. finally received recognition for her discovery\nS. at the international symposium", "c": "QPRS", "d": ["PQRS", "QRPS", "RPQS"], "e": "Q introduces the subject ('the young scientist'), P adds the relative clause ('who had worked...'), R gives the main predicate ('finally received...'), and S states the location ('at the international symposium').", "s": "Subject (Q) + Relative Clause (P) + Verb/Object (R) + Place (S)."}]}];

  const tests = RAW_CHAPTERS.map((ch) => ({
    id: ch.id,
    title: ch.title,
    subtitle: ch.subtitle,
    questions: ch.questions.map((item, idx) =>
      buildQuestion(`${ch.id}-q${String(idx + 1).padStart(2, '0')}`, item, hash(`${ch.id}-${idx}-${item.q}`))
    )
  }));

  root.SSC_CHSL_CHAPTER_ENG_DATA = {
    exam: {
      name: "SSC CHSL \u2014 English Chapter-Wise PYQs",
      totalQuestions: 50,
      totalMarks: 100,
      totalMinutes: 30,
      correctMarks: 2,
      incorrectPenalty: 0.5
    },
    tests,
    questionTotal: tests.reduce((s, t) => s + t.questions.length, 0)
  };
})(globalThis);
